def render_table(headers, rows, aligns):
    if len(headers) == 0:
        return []
    if len(aligns) != len(headers):
        return None
    for ch in aligns:
        if ch not in ('l', 'r', 'c'):
            return None

    header_texts = [str(h).replace('|', '\\|') for h in headers]

    row_texts = []
    for row in rows:
        if len(row) > len(headers):
            return None
        texts = [str(cell).replace('|', '\\|') for cell in row]
        if len(texts) < len(headers):
            texts.extend([''] * (len(headers) - len(texts)))
        row_texts.append(texts)

    widths = []
    for i in range(len(headers)):
        w = len(header_texts[i])
        for rt in row_texts:
            if len(rt[i]) > w:
                w = len(rt[i])
        widths.append(max(w, 3))

    def align_text(text, width, align):
        extra = width - len(text)
        if align == 'l':
            return text + ' ' * extra
        if align == 'r':
            return ' ' * extra + text
        left = extra // 2
        return ' ' * left + text + ' ' * (extra - left)

    def content_line(texts):
        parts = ['|']
        for i, text in enumerate(texts):
            parts.append(' ' + align_text(text, widths[i], aligns[i]) + ' |')
        return ''.join(parts)

    def separator_line():
        parts = ['|']
        for i in range(len(headers)):
            w = widths[i]
            if aligns[i] == 'l':
                seg = ':' + '-' * (w + 1)
            elif aligns[i] == 'r':
                seg = '-' * (w + 1) + ':'
            else:
                seg = ':' + '-' * w + ':'
            parts.append(seg + '|')
        return ''.join(parts)

    lines = [content_line(header_texts), separator_line()]
    for rt in row_texts:
        lines.append(content_line(rt))
    return lines

