import heapq

def lex_shortest_path(edges, src, dst):
    for edge in edges:
        if edge[2] < 1:
            return None
    if src == dst:
        return [0, [src]]
    adj = {}
    for u, v, w in edges:
        adj.setdefault(u, []).append((v, w))
    INF = float('inf')
    dist = {src: 0}
    pq = [(0, src)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist.get(u, INF):
            continue
        for v, w in adj.get(u, []):
            nd = d + w
            if nd < dist.get(v, INF):
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    if dst not in dist:
        return None
    path = [src]
    u = src
    while u != dst:
        best = None
        du = dist[u]
        for v, w in adj.get(u, []):
            if dist.get(v, INF) == du + w:
                if best is None or v < best:
                    best = v
        path.append(best)
        u = best
    return [dist[dst], path]

def render_table(headers, rows, aligns):
    if not headers:
        return []
    if len(aligns) != len(headers):
        return None
    for ch in aligns:
        if ch not in ('l', 'r', 'c'):
            return None
    for row in rows:
        if len(row) > len(headers):
            return None

    def text(value):
        return str(value).replace('|', '\\|')

    header_texts = [text(h) for h in headers]
    padded_rows = []
    for row in rows:
        r = list(row) + [''] * (len(headers) - len(row))
        padded_rows.append([text(v) for v in r])

    widths = []
    for j in range(len(headers)):
        w = len(header_texts[j])
        for r in padded_rows:
            if len(r[j]) > w:
                w = len(r[j])
        if w < 3:
            w = 3
        widths.append(w)

    def aligned(s, w, a):
        extra = w - len(s)
        if a == 'l':
            return s + ' ' * extra
        if a == 'r':
            return ' ' * extra + s
        left = extra // 2
        return ' ' * left + s + ' ' * (extra - left)

    lines = []
    lines.append('|' + ''.join(
        ' ' + aligned(header_texts[j], widths[j], aligns[j]) + ' ' + '|'
        for j in range(len(headers))
    ))

    sep_segments = []
    for j in range(len(headers)):
        w = widths[j]
        a = aligns[j]
        if a == 'l':
            seg = ':' + '-' * (w + 1)
        elif a == 'r':
            seg = '-' * (w + 1) + ':'
        else:
            seg = ':' + '-' * w + ':'
        sep_segments.append(seg)
    lines.append('|' + ''.join(seg + '|' for seg in sep_segments))

    for r in padded_rows:
        lines.append('|' + ''.join(
            ' ' + aligned(r[j], widths[j], aligns[j]) + ' ' + '|'
            for j in range(len(headers))
        ))

    return lines

def shell_words(line, env):
    n = len(line)

    def is_name_start(c):
        return ('A' <= c <= 'Z') or ('a' <= c <= 'z') or c == '_'

    def is_name_char(c):
        return is_name_start(c) or ('0' <= c <= '9')

    def expand(pos):
        if pos + 1 >= n:
            return '$', pos + 1
        nxt = line[pos + 1]
        if nxt == '{':
            end = line.find('}', pos + 2)
            if end == -1:
                return None, None
            name = line[pos + 2:end]
            if not name:
                return None, None
            if not is_name_start(name[0]):
                return None, None
            for c in name[1:]:
                if not is_name_char(c):
                    return None, None
            return env.get(name, ''), end + 1
        if not is_name_start(nxt):
            return '$', pos + 1
        j = pos + 1
        j += 1
        while j < n and is_name_char(line[j]):
            j += 1
        name = line[pos + 1:j]
        return env.get(name, ''), j

    words = []
    word = []
    had_quoted = False
    i = 0
    while i < n:
        ch = line[i]
        if ch == '\'':
            end = line.find('\'', i + 1)
            if end == -1:
                return None
            word.append(line[i + 1:end])
            had_quoted = True
            i = end + 1
            continue
        if ch == '"':
            had_quoted = True
            j = i + 1
            closed = False
            while j < n:
                c = line[j]
                if c == '"':
                    closed = True
                    i = j + 1
                    break
                if c == '\\':
                    if j + 1 >= n:
                        return None
                    nxt = line[j + 1]
                    if nxt == '"' or nxt == '\\' or nxt == '$':
                        word.append(nxt)
                        j += 2
                    else:
                        word.append('\\')
                        word.append(nxt)
                        j += 2
                    continue
                if c == '$':
                    val, new_pos = expand(j)
                    if val is None:
                        return None
                    word.append(val)
                    j = new_pos
                    continue
                word.append(c)
                j += 1
            if not closed:
                return None
            continue
        if ch == '\\':
            if i + 1 >= n:
                return None
            word.append(line[i + 1])
            i += 2
            continue
        if ch == '$':
            val, new_pos = expand(i)
            if val is None:
                return None
            word.append(val)
            i = new_pos
            continue
        if ch == ' ' or ch == '\t':
            if word or had_quoted:
                words.append(''.join(word))
            word = []
            had_quoted = False
            i += 1
            continue
        word.append(ch)
        i += 1
    if word or had_quoted:
        words.append(''.join(word))
    return words

def json_select(doc, path):
    if not isinstance(path, str):
        return None
    if ' ' in path:
        return None
    n = len(path)
    if n == 0 or path[0] != '$':
        return None

    FIRST = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz_'
    REST = FIRST + '0123456789'

    def parse_name(i):
        if i >= n or path[i] not in FIRST:
            return None
        j = i + 1
        while j < n and path[j] in REST:
            j += 1
        return path[i:j], j

    def recurse(v, name):
        out = []
        stack = [v]
        while stack:
            node = stack.pop()
            if isinstance(node, dict):
                if name in node:
                    out.append(node[name])
                children = list(node.values())
                for val in reversed(children):
                    stack.append(val)
            elif isinstance(node, list):
                for val in reversed(node):
                    stack.append(val)
        return out

    steps = []
    i = 1
    while i < n:
        c = path[i]
        if c == '.':
            if i + 1 < n and path[i + 1] == '.':
                m = parse_name(i + 2)
                if m is None:
                    return None
                name, i = m
                steps.append(('recurse', name))
            else:
                m = parse_name(i + 1)
                if m is None:
                    return None
                name, i = m
                steps.append(('key', name))
        elif c == '[':
            j = i + 1
            if j >= n:
                return None
            ch = path[j]
            if ch == '*':
                j += 1
                if j >= n or path[j] != ']':
                    return None
                j += 1
                steps.append(('all',))
                i = j
            elif ch == '\'':
                j += 1
                text = []
                while True:
                    if j >= n:
                        return None
                    ch = path[j]
                    if ch == '\\':
                        if j + 1 >= n:
                            return None
                        nxt = path[j + 1]
                        if nxt == '\'':
                            text.append('\'')
                            j += 2
                        elif nxt == '\\':
                            text.append('\\')
                            j += 2
                        else:
                            return None
                    elif ch == '\'':
                        j += 1
                        break
                    else:
                        text.append(ch)
                        j += 1
                if j >= n or path[j] != ']':
                    return None
                j += 1
                steps.append(('key', ''.join(text)))
                i = j
            else:
                minus = False
                if ch == '-':
                    minus = True
                    j += 1
                if j >= n or not ('0' <= path[j] <= '9'):
                    return None
                dstart = j
                while j < n and '0' <= path[j] <= '9':
                    j += 1
                digits = path[dstart:j]
                if len(digits) > 1 and digits[0] == '0':
                    return None
                if j >= n or path[j] != ']':
                    return None
                j += 1
                val = int(digits)
                if minus:
                    val = -val
                steps.append(('index', val))
                i = j
        else:
            return None

    current = [doc]
    for step in steps:
        typ = step[0]
        new_current = []
        if typ == 'key':
            name = step[1]
            for v in current:
                if isinstance(v, dict) and name in v:
                    new_current.append(v[name])
        elif typ == 'index':
            idx = step[1]
            for v in current:
                if isinstance(v, list):
                    if idx < 0:
                        pos = len(v) + idx
                    else:
                        pos = idx
                    if 0 <= pos < len(v):
                        new_current.append(v[pos])
        elif typ == 'all':
            for v in current:
                if isinstance(v, list):
                    new_current.extend(v)
                elif isinstance(v, dict):
                    for val in v.values():
                        new_current.append(val)
        else:
            name = step[1]
            for v in current:
                new_current.extend(recurse(v, name))
        current = new_current
    return current

