        return None
    for ch in aligns:
        if ch not in ('l', 'r', 'c'):
            return None
    n = len(headers)
    for row in rows:
        if len(row) > n:
            return None

    def cell_text(v):
        return str(v).replace('|', '\\|')

    header_texts = [cell_text(h) for h in headers]

    padded_rows = []
    for row in rows:
        cells = [cell_text(v) for v in row]
        if len(cells) < n:
            cells = cells + [''] * (n - len(cells))
        padded_rows.append(cells)

    widths = []
    for i in range(n):
        w = len(header_texts[i])
        for cells in padded_rows:
            if len(cells[i]) > w:
                w = len(cells[i])
        if w < 3:
            w = 3
        widths.append(w)

    def content_line(texts):
        parts = ['|']
        for i in range(n):
            t = texts[i]
            extra = widths[i] - len(t)
            ch = aligns[i]
            if ch == 'l':
                padded = t + ' ' * extra
            elif ch == 'r':
                padded = ' ' * extra + t
            else:
                left = extra // 2
                padded = ' ' * left + t + ' ' * (extra - left)
            parts.append(' ' + padded + ' ' + '|')
        return ''.join(parts)

    lines = [content_line(header_texts)]

    sep_parts = ['|']
    for i in range(n):
        w = widths[i]
        ch = aligns[i]
        if ch == 'l':
            seg = ':' + '-' * (w + 1)
        elif ch == 'r':
            seg = '-' * (w + 1) + ':'
        else:
            seg = ':' + '-' * w + ':'
        sep_parts.append(seg + '|')
    lines.append(''.join(sep_parts))

    for cells in padded_rows:
        lines.append(content_line(cells))

    return lines

