import heapq

def lex_shortest_path(edges, src, dst):
    for edge in edges:
        if edge[2] < 1:
            return None
    if src == dst:
        return [0, [src]]
    adj = {}
    for u, v, w in edges:
        adj.setdefault(u, []).append((v, w))
    dist = {src: 0}
    pq = [(0, src)]
    while pq:
        d, u = heapq.heappop(pq)
        if d != dist.get(u):
            continue
        for v, w in adj.get(u, ()):
            nd = d + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    if dst not in dist:
        return None
    path = [src]
    cur = src
    while cur != dst:
        du = dist[cur]
        best = None
        for v, w in adj.get(cur, ()):
            if dist.get(v) == du + w and (best is None or v < best):
                best = v
        if best is None:
            return None
        path.append(best)
        cur = best
    return [dist[dst], path]

