def render_table(headers, rows, aligns):
    if not headers:
        return []
    if len(aligns) != len(headers):
        return None
    if any(ch not in ('l', 'r', 'c') for ch in aligns):
        return None
    cols = len(headers)
    for row in rows:
        if len(row) > cols:
            return None

    headers_text = [str(h).replace('|', '\\|') for h in headers]
    rows_text = []
    for row in rows:
        cells = [str(c).replace('|', '\\|') for c in row]
        while len(cells) < cols:
            cells.append('')
        rows_text.append(cells)

    widths = []
    for j in range(cols):
        w = len(headers_text[j])
        for rt in rows_text:
            if len(rt[j]) > w:
                w = len(rt[j])
        if w < 3:
            w = 3
        widths.append(w)

    def pad(text, align, width):
        extra = width - len(text)
        if align == 'l':
            return text + ' ' * extra
        if align == 'r':
            return ' ' * extra + text
        left = extra // 2
        return ' ' * left + text + ' ' * (extra - left)

    lines = []
    header_line = '|' + ''.join(
        ' ' + pad(headers_text[j], aligns[j], widths[j]) + ' ' + '|'
        for j in range(cols)
    )
    lines.append(header_line)

    sep_parts = []
    for j in range(cols):
        w = widths[j]
        a = aligns[j]
        if a == 'l':
            seg = ':' + '-' * (w + 1)
        elif a == 'r':
            seg = '-' * (w + 1) + ':'
        else:
            seg = ':' + '-' * w + ':'
        sep_parts.append(seg + '|')
    lines.append('|' + ''.join(sep_parts))

    for rt in rows_text:
        line = '|' + ''.join(
            ' ' + pad(rt[j], aligns[j], widths[j]) + ' ' + '|'
            for j in range(cols)
        )
        lines.append(line)

    return lines

def poly_expand(expr):
    def is_int_token(tok):
        return tok is not None and len(tok) > 0 and all('0' <= ch <= '9' for ch in tok)

    def tokenize(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch == ' ':
                i += 1
                continue
            if '0' <= ch <= '9':
                j = i
                while j < n and '0' <= s[j] <= '9':
                    j += 1
                tokens.append(s[i:j])
                i = j
                continue
            if ch in "+-*^()x":
                tokens.append(ch)
                i += 1
                continue
            raise ValueError("invalid character")
        return tokens

    def add(a, b):
        r = dict(a)
        for d, c in b.items():
            nc = r.get(d, 0) + c
            if nc:
                r[d] = nc
            else:
                r.pop(d, None)
        return r

    def neg(a):
        return {d: -c for d, c in a.items()}

    def mul(a, b):
        r = {}
        for d1, c1 in a.items():
            for d2, c2 in b.items():
                d = d1 + d2
                r[d] = r.get(d, 0) + c1 * c2
        return {d: c for d, c in r.items() if c}

    def parse_base():
        if pos[0] >= len(tokens):
            raise ValueError("unexpected end")
        tok = tokens[pos[0]]
        if is_int_token(tok):
            pos[0] += 1
            return {0: int(tok)}
        if tok == 'x':
            pos[0] += 1
            return {1: 1}
        if tok == '(':
            pos[0] += 1
            p = parse_expr()
            if pos[0] >= len(tokens) or tokens[pos[0]] != ')':
                raise ValueError("expected )")
            pos[0] += 1
            return p
        raise ValueError("bad base")

    def parse_factor():
        if pos[0] < len(tokens) and tokens[pos[0]] == '-':
            pos[0] += 1
            return neg(parse_factor())
        base = parse_base()
        if pos[0] < len(tokens) and tokens[pos[0]] == '^':
            pos[0] += 1
            if pos[0] >= len(tokens):
                raise ValueError("expected exponent")
            tok = tokens[pos[0]]
            if not is_int_token(tok):
                raise ValueError("bad exponent")
            pos[0] += 1
            e = int(tok)
            if e > 20:
                raise ValueError("exponent too large")
            if e == 0:
                return {0: 1}
            result = {0: 1}
            for _ in range(e):
                result = mul(result, base)
            return result
        return base

    def parse_term():
        p = parse_factor()
        while pos[0] < len(tokens) and tokens[pos[0]] == '*':
            pos[0] += 1
            p = mul(p, parse_factor())
        return p

    def parse_expr():
        p = parse_term()
        while pos[0] < len(tokens) and tokens[pos[0]] in ('+', '-'):
            op = tokens[pos[0]]
            pos[0] += 1
            q = parse_term()
            p = add(p, q) if op == '+' else add(p, neg(q))
        return p

    try:
        tokens = tokenize(expr)
        pos = [0]
        p = parse_expr()
        if pos[0] != len(tokens):
            raise ValueError("trailing tokens")
    except ValueError:
        return None

    if not p:
        return '0'

    terms = []
    for d in sorted(p, reverse=True):
        c = p[d]
        if c == 0:
            continue
        ac = abs(c)
        if d == 0:
            body = str(ac)
        else:
            body = 'x' if ac == 1 else str(ac) + 'x'
            if d > 1:
                body += '^' + str(d)
        terms.append((c < 0, body))

    first_sign, first_body = terms[0]
    out = ('-' if first_sign else '') + first_body
    for sign, body in terms[1:]:
        out += ('-' if sign else '+') + body
    return out

