def shell_words(line, env):
    words = []
    current = []
    has_quote = False
    i = 0
    n = len(line)
    in_single = False
    in_double = False

    def is_name_start(c):
        return c == '_' or ('A' <= c <= 'Z') or ('a' <= c <= 'z')

    def is_name_char(c):
        return c == '_' or ('A' <= c <= 'Z') or ('a' <= c <= 'z') or ('0' <= c <= '9')

    def expand_at(pos):
        j = pos + 1
        if j < n and line[j] == '{':
            k = line.find('}', j + 1)
            if k == -1:
                return None
            name = line[j + 1:k]
            if not name:
                return None
            if not is_name_start(name[0]):
                return None
            for c in name[1:]:
                if not is_name_char(c):
                    return None
            current.append(env.get(name, ''))
            return k + 1
        if j < n and is_name_start(line[j]):
            k = j
            while k < n and is_name_char(line[k]):
                k += 1
            current.append(env.get(line[j:k], ''))
            return k
        current.append('$')
        return pos + 1

    while i < n:
        ch = line[i]
        if in_single:
            if ch == "'":
                in_single = False
                i += 1
            else:
                current.append(ch)
                i += 1
            continue
        if in_double:
            if ch == '"':
                in_double = False
                i += 1
                continue
            if ch == '\\':
                if i + 1 < n:
                    nxt = line[i + 1]
                    if nxt == '"' or nxt == '\\' or nxt == '$':
                        current.append(nxt)
                        i += 2
                        continue
                current.append('\\')
                i += 1
                continue
            if ch == '$':
                res = expand_at(i)
                if res is None:
                    return None
                i = res
                continue
            current.append(ch)
            i += 1
            continue
        if ch == ' ' or ch == '\t':
            if current or has_quote:
                words.append(''.join(current))
            current = []
            has_quote = False
            i += 1
            continue
        if ch == "'":
            in_single = True
            has_quote = True
            i += 1
            continue
        if ch == '"':
            in_double = True
            has_quote = True
            i += 1
            continue
        if ch == '\\':
            if i + 1 >= n:
                return None
            current.append(line[i + 1])
            i += 2
            continue
        if ch == '$':
            res = expand_at(i)
            if res is None:
                return None
            i = res
            continue
        current.append(ch)
        i += 1

    if in_single or in_double:
        return None
    if current or has_quote:
        words.append(''.join(current))
    return words

