                words.append(''.join(cur))
            cur = []
            has_quoted = False
            i += 1
            continue
        if ch == '\\':
            if i + 1 >= n:
                return None
            cur.append(line[i + 1])
            i += 2
            continue
        if ch == '\'':
            has_quoted = True
            j = line.find('\'', i + 1)
            if j == -1:
                return None
            cur.append(line[i + 1:j])
            i = j + 1
            continue
        if ch == '"':
            has_quoted = True
            i += 1
            while i < n:
                c = line[i]
                if c == '"':
                    i += 1
                    break
                if c == '\\':
                    if i + 1 >= n:
                        return None
                    nxt = line[i + 1]
                    if nxt == '"' or nxt == '\\' or nxt == '$':
                        cur.append(nxt)
                        i += 2
                    else:
                        cur.append('\\')
                        i += 1
                    continue
                if c == '$':
                    if i + 1 >= n:
                        return None
                    nxt = line[i + 1]
                    if nxt == '{':
                        k = line.find('}', i + 2)
                        if k == -1:
                            return None
                        name = line[i + 2:k]
                        if _NAME_RE.fullmatch(name) is None:
                            return None
                        cur.append(env.get(name, ''))
                        i = k + 1
                    else:
                        m = _NAME_RE.match(line, i + 1)
                        if m is not None:
                            cur.append(env.get(m.group(0), ''))
                            i = m.end()
                        else:
                            cur.append('$')
                            i += 1
                    continue
                cur.append(c)
                i += 1
            else:
                return None
            continue
        if ch == '$':
            if i + 1 >= n:
                cur.append('$')
                i += 1
                continue
            nxt = line[i + 1]
            if nxt == '{':
                k = line.find('}', i + 2)
                if k == -1:
                    return None
                name = line[i + 2:k]
                if _NAME_RE.fullmatch(name) is None:
                    return None
                cur.append(env.get(name, ''))
                i = k + 1
                continue
            m = _NAME_RE.match(line, i + 1)
            if m is not None:
                cur.append(env.get(m.group(0), ''))
                i = m.end()
            else:
                cur.append('$')
                i += 1
            continue
        cur.append(ch)
        i += 1

    if cur or has_quoted:
        words.append(''.join(cur))
    return words

import calendar
from datetime import date


def cron_next(expr, start):
    def parse_num(s):
        if s == '':
            return None
        for ch in s:
            if not ('0' <= ch <= '9'):
                return None
        return int(s)

    def parse_item(item, mn, mx):
        if item.count('/') > 1:
            return None
        if '/' in item:
            base, step_str = item.split('/')
            step = parse_num(step_str)
            if step is None or step < 1:
                return None
        else:
            base, step = item, None
        if base == '*':
            if step is None:
                return set(range(mn, mx + 1))
            return set(range(mn, mx + 1, step))
        if '-' in base:
            parts = base.split('-')
            if len(parts) != 2:
                return None
            n = parse_num(parts[0])
            m = parse_num(parts[1])
            if n is None or m is None:
                return None
            if n > m:
                return None
            if n < mn or m > mx:
                return None
            if step is None:
                return set(range(n, m + 1))
            return set(range(n, m + 1, step))
        n = parse_num(base)
        if n is None:
            return None
        if n < mn or n > mx:
            return None
        if step is None:
            return {n}
        return set(range(n, mx + 1, step))

    def parse_field(text, mn, mx):
        if text == '*':
            return set(range(mn, mx + 1)), False
        values = set()
        for item in text.split(','):
            if item == '':
                return None
            vals = parse_item(item, mn, mx)
            if vals is None:
                return None
            values.update(vals)
        return values, True

    def parse_expr(expr):
        if not isinstance(expr, str):
            return None
        parts = expr.split(' ')
        if len(parts) != 5:
            return None
        fields = []
        for text, (mn, mx) in zip(parts, ((0, 59), (0, 23), (1, 31), (1, 12), (0, 6))):
            parsed = parse_field(text, mn, mx)
            if parsed is None:
                return None
            fields.append(parsed)
        return fields

    def parse_start(s):
        if not isinstance(s, str):
            return None
        if len(s) != 16:
            return None
        if s[4] != '-' or s[7] != '-' or s[10] != ' ' or s[13] != ':':
            return None
        for i, ch in enumerate(s):
            if i in (4, 7, 10, 13):
                continue
            if not ('0' <= ch <= '9'):
                return None
        year = int(s[0:4])
        month = int(s[5:7])
        day = int(s[8:10])
        hour = int(s[11:13])
        minute = int(s[14:16])
        if hour > 23 or minute > 59:
            return None
        try:
            date(year, month, day)
        except ValueError:
            return None
        return (year, month, day, hour, minute)

    parsed_start = parse_start(start)
    if parsed_start is None:
        return None
    fields = parse_expr(expr)
    if fields is None:
        return None

    minute_vals = fields[0][0]
    hour_vals = fields[1][0]
    dom_vals = fields[2][0]
    dom_restricted = fields[2][1]
    month_vals = fields[3][0]
    dow_vals = fields[4][0]
    dow_restricted = fields[4][1]

    year0, month0, day0, hour0, minute0 = parsed_start
    limit_year = year0 + 5
    if limit_year > 10000:
        limit_year = 10000

    hour_list = sorted(hour_vals)
    minute_list = sorted(minute_vals)
    bound = (limit_year, 1, 1)

    y, mo, d = year0, month0, day0
    while (y, mo, d) < bound:
        if mo in month_vals:
            wd = (date(y, mo, d).weekday() + 1) % 7
            dom_ok = d in dom_vals
            dow_ok = wd in dow_vals
            if dom_restricted and dow_restricted:
                day_ok = dom_ok or dow_ok
            else:
                day_ok = dom_ok and dow_ok
            if day_ok:
                is_start_day = (y == year0 and mo == month0 and d == day0)
                for hh in hour_list:
                    if is_start_day and hh < hour0:
                        continue
                    for mm in minute_list:
                        if is_start_day and hh == hour0 and mm <= minute0:
                            continue
                        return f"{y:04d}-{mo:02d}-{d:02d} {hh:02d}:{mm:02d}"
        d += 1
        if d > calendar.monthrange(y, mo)[1]:
            d = 1
            mo += 1
            if mo == 13:
                mo = 1
                y += 1
    return None

def bool_minterms(expr):
    if not isinstance(expr, str):
        return None
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c == ' ':
            i += 1
            continue
        if 'a' <= c <= 'z':
            j = i + 1
            while j < n and 'a' <= expr[j] <= 'z':
                j += 1
            tokens.append(('var', expr[i:j]))
            i = j
            continue
        if '0' <= c <= '9':
            j = i + 1
            while j < n and '0' <= expr[j] <= '9':
                j += 1
            run = expr[i:j]
            if run == '0':
                tokens.append(('const', False))
            elif run == '1':
                tokens.append(('const', True))
            else:
                return None
            i = j
            continue
        if c == '!':
            tokens.append(('not', None))
            i += 1
            continue
        if c == '&':
            tokens.append(('and', None))
            i += 1
            continue
        if c == '^':
            tokens.append(('xor', None))
            i += 1
            continue
        if c == '|':
            tokens.append(('or', None))
            i += 1
            continue
        if c == '(':
            tokens.append(('lparen', None))
            i += 1
            continue
        if c == ')':
            tokens.append(('rparen', None))
            i += 1
            continue
        if c == '-':
            if i + 1 < n and expr[i + 1] == '>':
                tokens.append(('imp', None))
                i += 2
                continue
            return None
        return None

    pos = [0]

    def peek():
        if pos[0] < len(tokens):
            return tokens[pos[0]][0]
        return None

    def parse_expr():
        node = parse_or()
        if peek() == 'imp':
            pos[0] += 1
            rhs = parse_expr()
            return ('imp', node, rhs)
        return node

    def parse_or():
        node = parse_xor()
        while peek() == 'or':
            pos[0] += 1
            rhs = parse_xor()
            node = ('or', node, rhs)
        return node

    def parse_xor():
        node = parse_and()
        while peek() == 'xor':
            pos[0] += 1
            rhs = parse_and()
            node = ('xor', node, rhs)
        return node

    def parse_and():
        node = parse_unary()
        while peek() == 'and':
            pos[0] += 1
            rhs = parse_unary()
            node = ('and', node, rhs)
        return node

    def parse_unary():
        if peek() == 'not':
            pos[0] += 1
            return ('not', parse_unary())
        return parse_primary()

    def parse_primary():
        if pos[0] >= len(tokens):
            raise ValueError('unexpected end')
        kind, value = tokens[pos[0]]
        if kind == 'var':
            pos[0] += 1
            return ('var', value)
        if kind == 'const':
            pos[0] += 1
            return ('const', value)
        if kind == 'lparen':
            pos[0] += 1
            node = parse_expr()
            if pos[0] >= len(tokens) or tokens[pos[0]][0] != 'rparen':
                raise ValueError('expected )')
            pos[0] += 1
            return node
        raise ValueError('unexpected token')

    try:
        if not tokens:
            return None
        ast = parse_expr()
        if pos[0] != len(tokens):
            return None
    except ValueError:
        return None

    var_set = set()

    def collect(node):
        tag = node[0]
        if tag == 'var':
            var_set.add(node[1])
        elif tag == 'not':
            collect(node[1])
        elif tag in ('and', 'xor', 'or', 'imp'):
            collect(node[1])
            collect(node[2])

    collect(ast)

    def evaluate(node, env):
        tag = node[0]
        if tag == 'const':
            return node[1]
        if tag == 'var':
            return env[node[1]]
        if tag == 'not':
            return not evaluate(node[1], env)
        if tag == 'and':
            return evaluate(node[1], env) and evaluate(node[2], env)
        if tag == 'xor':
            return evaluate(node[1], env) != evaluate(node[2], env)
        if tag == 'or':
            return evaluate(node[1], env) or evaluate(node[2], env)
        if tag == 'imp':
            return (not evaluate(node[1], env)) or evaluate(node[2], env)
        raise ValueError('bad node')

    names = sorted(var_set)
    k = len(names)
    minterms = []
    for index in range(1 << k):
        env = {}
        for i, name in enumerate(names):
            env[name] = ((index >> (k - 1 - i)) & 1) == 1
        if evaluate(ast, env):
            minterms.append(index)
    return [names, minterms]

import re
from datetime import datetime, timedelta


def cron_next(expr, start):
    if not isinstance(expr, str) or not isinstance(start, str):
        return None

    def digits(s):
        return s != '' and all('0' <= c <= '9' for c in s)

    m = re.fullmatch(r'([0-9]{4})-([0-9]{2})-([0-9]{2}) ([0-9]{2}):([0-9]{2})', start)
    if m is None:
        return None
    try:
        start_dt = datetime(int(m.group(1)), int(m.group(2)), int(m.group(3)),
                            int(m.group(4)), int(m.group(5)))
    except ValueError:
        return None

    fields = expr.split(' ')
    if len(fields) != 5:
        return None
    ranges = ((0, 59), (0, 23), (1, 31), (1, 12), (0, 6))
    sets = []
    restricted = []
    for field, (lo, hi) in zip(fields, ranges):
        if field == '':
            return None
        restricted.append(field != '*')
        values = set()
        for item in field.split(','):
            if item == '':
                return None
            step = None
            if '/' in item:
                base, _, step_str = item.partition('/')
                if '/' in step_str or not digits(step_str):
                    return None
                step = int(step_str)
                if step < 1:
                    return None
            else:
                base = item
            if base == '*':
                values.update(range(lo, hi + 1, step if step is not None else 1))
            elif '-' in base:
                parts = base.split('-')
                if len(parts) != 2 or not digits(parts[0]) or not digits(parts[1]):
                    return None
                n = int(parts[0])
                mm = int(parts[1])
                if n < lo or mm > hi or n > mm:
                    return None
                if step is None:
                    values.update(range(n, mm + 1))
                else:
                    values.update(range(n, mm + 1, step))
            else:
                if not digits(base):
                    return None
                n = int(base)
                if n < lo or n > hi:
                    return None
                if step is None:
                    values.add(n)
                else:
                    values.update(range(n, hi + 1, step))
        sets.append(values)

    minute_set, hour_set, dom_set, month_set, dow_set = sets
    dom_restricted = restricted[2]
    dow_restricted = restricted[4]

    max_dt = datetime(9999, 12, 31, 23, 59)
    if start_dt >= max_dt:
        return None
    current = start_dt + timedelta(minutes=1)
    end_year = min(start_dt.year + 5, 10000)

    def matches(dt):
        if dt.minute not in minute_set:
            return False
        if dt.hour not in hour_set:
            return False
        if dt.month not in month_set:
            return False
        dow = (dt.weekday() + 1) % 7
        if dom_restricted and dow_restricted:
            if dt.day not in dom_set and dow not in dow_set:
                return False
        else:
            if dom_restricted and dt.day not in dom_set:
                return False
            if dow_restricted and dow not in dow_set:
                return False
        return True

    def fmt(dt):
        return f'{dt.year:04d}-{dt.month:02d}-{dt.day:02d} {dt.hour:02d}:{dt.minute:02d}'

    if end_year < 10000:
        end = datetime(end_year, 1, 1)
        while current < end:
            if matches(current):
                return fmt(current)
            current += timedelta(minutes=1)
        return None
    while current <= max_dt:
        if matches(current):
            return fmt(current)
        if current == max_dt:
            break
        current += timedelta(minutes=1)
    return None

def order_book(ops):
    trades = []
    bids = []
    asks = []
    used_ids = set()

    for i, op in enumerate(ops):
        if not isinstance(op, list) or len(op) < 1:
            continue
        kind = op[0]

        if kind == 'limit':
            if len(op) != 5:
                continue
            _, oid, side, price, qty = op
            if side not in ('buy', 'sell'):
                continue
            if qty < 1:
                continue
            if price < 1:
                continue
            if oid in used_ids:
                continue
            used_ids.add(oid)

            remaining = qty
            if side == 'buy':
                while remaining > 0:
                    best = None
                    for a in asks:
                        if (best is None
                                or a['price'] < best['price']
                                or (a['price'] == best['price'] and a['time'] < best['time'])):
                            best = a
                    if best is None:
                        break
                    if best['price'] > price:
                        break
                    t = min(remaining, best['qty'])
                    trades.append([oid, best['id'], best['price'], t])
                    remaining -= t
                    best['qty'] -= t
                    if best['qty'] <= 0:
                        asks.remove(best)
                if remaining > 0:
                    bids.append({'id': oid, 'price': price, 'qty': remaining, 'time': i})
            else:
                while remaining > 0:
                    best = None
                    for b in bids:
                        if (best is None
                                or b['price'] > best['price']
                                or (b['price'] == best['price'] and b['time'] < best['time'])):
                            best = b
                    if best is None:
                        break
                    if best['price'] < price:
                        break
                    t = min(remaining, best['qty'])
                    trades.append([best['id'], oid, best['price'], t])
                    remaining -= t
                    best['qty'] -= t
                    if best['qty'] <= 0:
                        bids.remove(best)
                if remaining > 0:
                    asks.append({'id': oid, 'price': price, 'qty': remaining, 'time': i})

        elif kind == 'market':
            if len(op) != 4:
                continue
            _, oid, side, qty = op
            if side not in ('buy', 'sell'):
                continue
            if qty < 1:
                continue
            if oid in used_ids:
                continue
            used_ids.add(oid)

            remaining = qty
            if side == 'buy':
                while remaining > 0:
                    best = None
                    for a in asks:
                        if (best is None
                                or a['price'] < best['price']
                                or (a['price'] == best['price'] and a['time'] < best['time'])):
                            best = a
                    if best is None:
                        break
                    t = min(remaining, best['qty'])
                    trades.append([oid, best['id'], best['price'], t])
                    remaining -= t
                    best['qty'] -= t
                    if best['qty'] <= 0:
                        asks.remove(best)
            else:
                while remaining > 0:
                    best = None
                    for b in bids:
                        if (best is None
                                or b['price'] > best['price']
                                or (b['price'] == best['price'] and b['time'] < best['time'])):
                            best = b
                    if best is None:
                        break
                    t = min(remaining, best['qty'])
                    trades.append([best['id'], oid, best['price'], t])
                    remaining -= t
                    best['qty'] -= t
                    if best['qty'] <= 0:
                        bids.remove(best)
            # leftover market quantity is discarded

        elif kind == 'cancel':
            if len(op) != 2:
                continue
            _, oid = op
            for b in list(bids):
                if b['id'] == oid:
                    bids.remove(b)
                    break
            for a in list(asks):
                if a['id'] == oid:
                    asks.remove(a)
                    break

        else:
            continue

    bids_sorted = sorted(bids, key=lambda b: (-b['price'], b['time']))
    asks_sorted = sorted(asks, key=lambda a: (a['price'], a['time']))

    return {
        'trades': trades,
        'bids': [[b['id'], b['price'], b['qty']] for b in bids_sorted],
        'asks': [[a['id'], a['price'], a['qty']] for a in asks_sorted],
    }

def canonical_huffman(freqs):
    weights = {}
    for symbol, weight in freqs:
        if weight <= 0:
            continue
        weights[symbol] = weights.get(symbol, 0) + weight
    if not weights:
        return []
    if len(weights) == 1:
        symbol = next(iter(weights))
        return [[symbol, "0"]]

    depths = {symbol: 0 for symbol in weights}
    nodes = [
        {"weight": weight, "key": symbol, "symbols": {symbol}}
        for symbol, weight in weights.items()
    ]

    while len(nodes) > 1:
        nodes.sort(key=lambda node: (node["weight"], node["key"]))
        first, second = nodes[0], nodes[1]
        merged_symbols = first["symbols"] | second["symbols"]
        for symbol in merged_symbols:
            depths[symbol] += 1
        merged = {
            "weight": first["weight"] + second["weight"],
            "key": first["key"] if first["key"] < second["key"] else second["key"],
            "symbols": merged_symbols,
        }
        nodes = nodes[2:] + [merged]

    order = sorted(weights, key=lambda symbol: (depths[symbol], symbol))
    result = []
    previous_code = None
    previous_length = None
    for symbol in order:
        length = depths[symbol]
        if previous_length is None:
            code = 0
        else:
            code = (previous_code + 1) << (length - previous_length)
        result.append([symbol, format(code, "0{}b".format(length))])
        previous_code = code
        previous_length = length
    return result

def shell_words(line, env):
    n = len(line)
    words = []
    cur = []
    has_quoted = False
    i = 0

    def is_name_start(c):
        return ('A' <= c <= 'Z') or ('a' <= c <= 'z') or c == '_'

    def is_name_char(c):
        return is_name_start(c) or ('0' <= c <= '9')

    def expand(pos):
        # line[pos] == '$'; returns (text, next_pos) or None on error
        if pos + 1 < n and line[pos + 1] == '{':
            j = line.find('}', pos + 2)
            if j == -1:
                return None
            name = line[pos + 2:j]
            if not name or not is_name_start(name[0]):
                return None
            for ch in name[1:]:
                if not is_name_char(ch):
                    return None
            return env.get(name, ''), j + 1
        j = pos + 1
        if j >= n or not is_name_start(line[j]):
            return '$', pos + 1
        k = j
        while k < n and is_name_char(line[k]):
            k += 1
        return env.get(line[j:k], ''), k

    def flush():
        nonlocal has_quoted
        text = ''.join(cur)
        if text or has_quoted:
            words.append(text)
        cur.clear()
        has_quoted = False

    while i < n:
        c = line[i]
        if c == '\'':
            j = line.find('\'', i + 1)
            if j == -1:
                return None
            cur.append(line[i + 1:j])
            has_quoted = True
            i = j + 1
            continue
        if c == '"':
            has_quoted = True
            i += 1
            closed = False
            while i < n:
                d = line[i]
                if d == '"':
                    i += 1
                    closed = True
                    break
                if d == '\\':
                    if i + 1 < n and line[i + 1] in ('"', '\\', '$'):
                        cur.append(line[i + 1])
                        i += 2
                    else:
                        cur.append('\\')
                        i += 1
                    continue
                if d == '$':
                    r = expand(i)
                    if r is None:
                        return None
                    cur.append(r[0])
                    i = r[1]
                    continue
                cur.append(d)
                i += 1
            if not closed:
                return None
            continue
        if c == '\\':
            if i + 1 >= n:
                return None
            cur.append(line[i + 1])
            i += 2
            continue
        if c == '$':
            r = expand(i)
            if r is None:
                return None
            cur.append(r[0])
            i = r[1]
            continue
        if c == ' ' or c == '\t':
            flush()
            i += 1
            continue
        cur.append(c)
        i += 1

    flush()
    return words

def render_table(headers, rows, aligns):
    if len(aligns) != len(headers):
        return None
    for ch in aligns:
        if ch not in ('l', 'r', 'c'):
            return None
    for row in rows:
        if len(row) > len(headers):
            return None
    if not headers:
        return []

    def esc(v):
        return str(v).replace('|', '\\|')

    header_texts = [esc(h) for h in headers]
    row_texts = []
    for row in rows:
        texts = [esc(c) for c in row]
        if len(texts) < len(headers):
            texts = texts + [''] * (len(headers) - len(texts))
        row_texts.append(texts)

    widths = []
    for i in range(len(headers)):
        w = len(header_texts[i])
        for rt in row_texts:
            if len(rt[i]) > w:
                w = len(rt[i])
        widths.append(max(w, 3))

    def align_text(t, a, w):
        extra = w - len(t)
        if a == 'l':
            return t + ' ' * extra
        if a == 'r':
            return ' ' * extra + t
        left = extra // 2
        return ' ' * left + t + ' ' * (extra - left)

    def sep_seg(w, a):
        if a == 'l':
            return ':' + '-' * (w + 1)
        if a == 'r':
            return '-' * (w + 1) + ':'
        return ':' + '-' * w + ':'

    def content_line(texts):
        parts = []
        for t, a, w in zip(texts, aligns, widths):
            parts.append(' ' + align_text(t, a, w) + ' ' + '|')
        return '|' + ''.join(parts)

    def separator_line():
        return '|' + ''.join(sep_seg(w, a) + '|' for a, w in zip(aligns, widths))

    lines = [content_line(header_texts), separator_line()]
    for rt in row_texts:
        lines.append(content_line(rt))
    return lines

from fractions import Fraction

def rational_eval(expr):
    try:
        if not isinstance(expr, str):
            return 'error'
        tokens = []
        i = 0
        n = len(expr)
        while i < n:
            c = expr[i]
            if c == ' ' or c == '\t':
                i += 1
            elif '0' <= c <= '9':
                j = i
                while j < n and '0' <= expr[j] <= '9':
                    j += 1
                tokens.append(expr[i:j])
                i = j
            elif c in ('+', '-', '*', '/', '^', '(', ')'):
                tokens.append(c)
                i += 1
            else:
                return 'error'
        pos = 0

        def peek():
            return tokens[pos] if pos < len(tokens) else None

        def parse_expr():
            nonlocal pos
            value = parse_term()
            while peek() in ('+', '-'):
                op = tokens[pos]
                pos += 1
                rhs = parse_term()
                value = value + rhs if op == '+' else value - rhs
            return value

        def parse_term():
            nonlocal pos
            value = parse_unary()
            while peek() in ('*', '/'):
                op = tokens[pos]
                pos += 1
                rhs = parse_unary()
                if op == '*':
                    value = value * rhs
                else:
                    if rhs == 0:
                        raise ValueError('division by zero')
                    value = value / rhs
            return value

        def parse_unary():
            nonlocal pos
            if peek() == '-':
                pos += 1
                return -parse_unary()
            return parse_power()

        def parse_power():
            nonlocal pos
            base = parse_atom()
            if peek() == '^':
                pos += 1
                exponent = parse_unary()
                base = power_eval(base, exponent)
            return base

        def parse_atom():
            nonlocal pos
            tok = peek()
            if tok is None:
                raise ValueError('unexpected end')
            if tok == '(':
                pos += 1
                value = parse_expr()
                if peek() != ')':
                    raise ValueError('expected )')
                pos += 1
                return value
            if tok in ('+', '-', '*', '/', '^', '(', ')'):
                raise ValueError('unexpected token')
            pos += 1
            return Fraction(int(tok))

        def power_eval(base, exponent):
            if exponent.denominator != 1:
                raise ValueError('exponent not an integer')
            e = exponent.numerator
            if e > 64 or e < -64:
                raise ValueError('exponent out of range')
            if e == 0:
                return Fraction(1)
            if base == 0 and e < 0:
                raise ValueError('zero raised to negative power')
            return base ** e

        if not tokens:
            return 'error'
        result = parse_expr()
        if pos != len(tokens):
            return 'error'
        if result.denominator == 1:
            return str(result.numerator)
        return f"{result.numerator}/{result.denominator}"
    except Exception:
        return 'error'

def ledger(accounts, ops):
    state = {}
    for acc in accounts:
        name, balance, overdraft = acc
        state[name] = {
            'balance': balance,
            'overdraft': overdraft,
            'frozen': False,
            'wd': 0,
        }

    expected_len = {'dep': 3, 'wd': 3, 'xfer': 4, 'freeze': 2, 'thaw': 2, 'day': 1}
    rejected = []

    for i, op in enumerate(ops):
        reason = None
        try:
            kind = op[0]
            length = len(op)
        except Exception:
            kind = None
            length = None

        if kind not in expected_len or length != expected_len.get(kind):
            reason = 'bad_op'

        amt = None
        cost = None

        if reason is None:
            if kind in ('dep', 'wd', 'freeze', 'thaw'):
                if op[1] not in state:
                    reason = 'no_account'
            elif kind == 'xfer':
                if op[1] not in state or op[2] not in state:
                    reason = 'no_account'

        if reason is None and kind == 'xfer' and op[1] == op[2]:
            reason = 'same_account'

        if reason is None and kind in ('dep', 'wd', 'xfer'):
            amt = op[3] if kind == 'xfer' else op[2]
            if amt < 1:
                reason = 'bad_amount'

        if reason is None and kind == 'wd':
            if state[op[1]]['frozen']:
                reason = 'frozen'
        elif reason is None and kind == 'xfer':
            if state[op[1]]['frozen']:
                reason = 'frozen'

        if reason is None and kind == 'wd':
            s = state[op[1]]
            fee = 0 if s['wd'] < 3 else 2
            cost = amt + fee
            if s['balance'] - cost < -s['overdraft']:
                reason = 'insufficient'
        elif reason is None and kind == 'xfer':
            s = state[op[1]]
            cost = amt + 1
            if s['balance'] - cost < -s['overdraft']:
                reason = 'insufficient'

        if reason is not None:
            rejected.append([i, reason])
            continue

        if kind == 'dep':
            state[op[1]]['balance'] += amt
        elif kind == 'wd':
            s = state[op[1]]
            s['balance'] -= cost
            s['wd'] += 1
        elif kind == 'xfer':
            state[op[1]]['balance'] -= cost
            state[op[2]]['balance'] += amt
        elif kind == 'freeze':
            state[op[1]]['frozen'] = True
        elif kind == 'thaw':
            state[op[1]]['frozen'] = False
        elif kind == 'day':
            for s in state.values():
                s['wd'] = 0

    return {
        'balances': [[name, state[name]['balance']] for name in sorted(state)],
        'rejected': rejected,
    }

def _time_to_minutes(s):
    if s == '24:00':
        return 1440
    if not isinstance(s, str) or len(s) != 5 or s[2] != ':':
        return None
    hh = s[:2]
    mm = s[3:]
    if not (all('0' <= c <= '9' for c in hh) and all('0' <= c <= '9' for c in mm)):
        return None
    h = int(hh)
    m = int(mm)
    if h > 23 or m > 59:
        return None
    return h * 60 + m


def _minutes_to_time(m):
    if m == 1440:
        return '24:00'
    return f'{m // 60:02d}:{m % 60:02d}'


def common_free_slots(calendars, day_start, day_end, min_len):
    if min_len < 1:
        return None
    ds = _time_to_minutes(day_start)
    de = _time_to_minutes(day_end)
    if ds is None or de is None:
        return None
    intervals = []
    for entry in calendars:
        offset = entry[0]
        for iv in entry[1]:
            ls = _time_to_minutes(iv[0])
            le = _time_to_minutes(iv[1])
            if ls is None or le is None:
                return None
            if le <= ls:
                continue
            us = ls - offset
            ue = le - offset
            if us < ds:
                us = ds
            if ue > de:
                ue = de
            if us < ue:
                intervals.append((us, ue))
    if de <= ds:
        return []
    intervals.sort(key=lambda x: (x[0], x[1]))
    merged = []
    for s, e in intervals:
        if merged and s <= merged[-1][1]:
            if e > merged[-1][1]:
                merged[-1][1] = e
        else:
            merged.append([s, e])
    free = []
    cur = ds
    for s, e in merged:
        if s > cur and s - cur >= min_len:
            free.append((cur, s))
        if e > cur:
            cur = e
    if de - cur >= min_len:
        free.append((cur, de))
    return [[_minutes_to_time(s), _minutes_to_time(e)] for s, e in free]

def token_bucket(capacity, refill_ms, requests):
    if capacity < 1 or refill_ms < 1:
        return None
    tokens = capacity
    mark = 0
    accepted = []
    last_t = None
    for i, req in enumerate(requests):
        t, cost = req[0], req[1]
        if cost < 1 or t < 0:
            continue
        if last_t is not None and t < last_t:
            continue
        last_t = t
        if tokens < capacity:
            g = (t - mark) // refill_ms
            if tokens + g >= capacity:
                tokens = capacity
            else:
                tokens += g
                mark += g * refill_ms
        if tokens == capacity:
            mark = t
        if cost <= tokens:
            accepted.append(i)
            tokens -= cost
    return accepted

def min_coins_lex(coins, amount):
    if amount < 0:
        return None
    if amount == 0:
        return []
    denoms = sorted({c for c in coins if c > 0}, reverse=True)
    if not denoms:
        return None
    zeros = tuple([0] * len(denoms))
    dp = [None] * (amount + 1)
    dp[0] = (0, zeros)
    for a in range(amount + 1):
        cur = dp[a]
        if cur is None:
            continue
        cnt, counts = cur
        for idx, c in enumerate(denoms):
            b = a + c
            if b > amount:
                continue
            new_counts = list(counts)
            new_counts[idx] += 1
            new_counts = tuple(new_counts)
            new_cnt = cnt + 1
            best = dp[b]
            if best is None:
                dp[b] = (new_cnt, new_counts)
            else:
                best_cnt, best_counts = best
                if new_cnt < best_cnt or (new_cnt == best_cnt and new_counts > best_counts):
                    dp[b] = (new_cnt, new_counts)
    best = dp[amount]
    if best is None:
        return None
    _, counts = best
    result = []
    for idx, c in enumerate(denoms):
        result.extend([c] * counts[idx])
    return result

import calendar
import re
from datetime import date


def monthly_occurrences(start, rule, count):
    _WEEKDAYS = ("mon", "tue", "wed", "thu", "fri", "sat", "sun")

    def parse_rule(rule):
        if not isinstance(rule, str):
            return None
        parts = rule.split(":")
        if len(parts) < 2:
            return None
        head = parts[0]
        if head == "day":
            if len(parts) != 2:
                return None
            s = parts[1]
            neg = False
            if s.startswith("-"):
                neg = True
                s = s[1:]
            if re.fullmatch(r"(?:[1-9]|1[0-9]|2[0-9]|3[01])", s) is None:
                return None
            return ("day", neg, int(s), None)
        if head == "nth":
            if len(parts) != 3:
                return None
            s = parts[1]
            neg = False
            if s.startswith("-"):
                neg = True
                s = s[1:]
            if re.fullmatch(r"[1-5]", s) is None:
                return None
            wd = parts[2]
            if wd not in _WEEKDAYS:
                return None
            return ("nth", neg, int(s), wd)
        return None

    if not isinstance(start, str):
        return None
    if re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2}", start) is None:
        return None
    try:
        start_date = date(int(start[:4]), int(start[5:7]), int(start[8:10]))
    except ValueError:
        return None

    parsed = parse_rule(rule)
    if parsed is None:
        return None

    if count <= 0:
        return []

    kind, neg, n, wd = parsed

    def candidate(y, m):
        month_len = calendar.monthrange(y, m)[1]
        if kind == "day":
            if neg:
                day = month_len - (n - 1)
            else:
                day = n
            if day < 1 or day > month_len:
                return None
            return date(y, m, day)
        target = _WEEKDAYS.index(wd)
        seen = 0
        if not neg:
            for d in range(1, month_len + 1):
                if date(y, m, d).weekday() == target:
                    seen += 1
                    if seen == n:
                        return date(y, m, d)
            return None
        for d in range(month_len, 0, -1):
            if date(y, m, d).weekday() == target:
                seen += 1
                if seen == n:
                    return date(y, m, d)
        return None

    result = []
    y, m = start_date.year, start_date.month
    while len(result) < count:
        if (y, m) > (9999, 12):
            break
        cand = candidate(y, m)
        if cand is not None and cand >= start_date:
            result.append(cand.isoformat())
        m += 1
        if m == 13:
            m = 1
            y += 1
    return result

def ledger(accounts, ops):
    state = {}
    for name, balance, overdraft in accounts:
        state[name] = {'balance': balance, 'overdraft': overdraft, 'frozen': False, 'wd_count': 0}
    rejected = []
    expected_lengths = {'dep': 3, 'wd': 3, 'xfer': 4, 'freeze': 2, 'thaw': 2, 'day': 1}
    for index, op in enumerate(ops):
        if not isinstance(op, (list, tuple)) or len(op) == 0:
            rejected.append([index, 'bad_op'])
            continue
        kind = op[0]
        if not isinstance(kind, str) or kind not in expected_lengths or len(op) != expected_lengths[kind]:
            rejected.append([index, 'bad_op'])
            continue
        if kind == 'day':
            for st in state.values():
                st['wd_count'] = 0
            continue
        if kind == 'freeze' or kind == 'thaw':
            a = op[1]
            if a not in state:
                rejected.append([index, 'no_account'])
                continue
            state[a]['frozen'] = (kind == 'freeze')
            continue
        if kind == 'dep':
            a, amt = op[1], op[2]
            if a not in state:
                rejected.append([index, 'no_account'])
                continue
            if amt < 1:
                rejected.append([index, 'bad_amount'])
                continue
            state[a]['balance'] += amt
            continue
        if kind == 'wd':
            a, amt = op[1], op[2]
            if a not in state:
                rejected.append([index, 'no_account'])
                continue
            if amt < 1:
                rejected.append([index, 'bad_amount'])
                continue
            st = state[a]
            if st['frozen']:
                rejected.append([index, 'frozen'])
                continue
            fee = 0 if st['wd_count'] < 3 else 2
            cost = amt + fee
            if st['balance'] - cost < -st['overdraft']:
                rejected.append([index, 'insufficient'])
                continue
            st['balance'] -= cost
            st['wd_count'] += 1
            continue
        # xfer
        frm, to, amt = op[1], op[2], op[3]
        if frm not in state or to not in state:
            rejected.append([index, 'no_account'])
            continue
        if frm == to:
            rejected.append([index, 'same_account'])
            continue
        if amt < 1:
            rejected.append([index, 'bad_amount'])
            continue
        st = state[frm]
        if st['frozen']:
            rejected.append([index, 'frozen'])
            continue
        cost = amt + 1
        if st['balance'] - cost < -st['overdraft']:
            rejected.append([index, 'insufficient'])
            continue
        st['balance'] -= cost
        state[to]['balance'] += amt
    balances = [[name, state[name]['balance']] for name in sorted(state)]
    return {'balances': balances, 'rejected': rejected}

def min_coins_lex(coins, amount):
    if amount < 0:
        return None
    if amount == 0:
        return []
    denoms = sorted({c for c in coins if c > 0})
    if not denoms:
        return None
    dp = [None] * (amount + 1)
    dp[0] = (0, ())
    for i in range(1, amount + 1):
        best = None
        for c in denoms:
            if c > i:
                continue
            prev = dp[i - c]
            if prev is None:
                continue
            cnt = prev[0] + 1
            cand = tuple(sorted(prev[1] + (c,), reverse=True))
            if best is None:
                best = (cnt, cand)
            elif cnt < best[0] or (cnt == best[0] and cand > best[1]):
                best = (cnt, cand)
        dp[i] = best
    res = dp[amount]
    if res is None:
        return None
    return list(res[1])

import calendar
from datetime import date


def date_diff_ymd(a, b):
    def parse(s):
        if not isinstance(s, str) or len(s) != 10:
            return None
        if s[4] != '-' or s[7] != '-':
            return None
        for i, ch in enumerate(s):
            if i == 4 or i == 7:
                continue
            if '0' <= ch <= '9':
                continue
            return None
        try:
            return date(int(s[:4]), int(s[5:7]), int(s[8:]))
        except ValueError:
            return None

    def shift(d, k):
        idx = (d.month - 1) + k
        y = d.year + idx // 12
        m = idx % 12 + 1
        return date(y, m, min(d.day, calendar.monthrange(y, m)[1]))

    def diff(x, y):
        T = (y.year - x.year) * 12 + (y.month - x.month)
        while T > 0 and shift(x, T) > y:
            T -= 1
        return [T // 12, T % 12, (y - shift(x, T)).days]

    da = parse(a)
    db = parse(b)
    if da is None or db is None:
        return None
    if da <= db:
        return diff(da, db)
    r = diff(db, da)
    return [-r[0], -r[1], -r[2]]

def spreadsheet_eval(cells):
    def is_digit(ch):
        return '0' <= ch <= '9'

    def is_ref(tok):
        if len(tok) < 2:
            return False
        if not ('A' <= tok[0] <= 'Z'):
            return False
        row = tok[1:]
        if len(row) == 1:
            return '1' <= row[0] <= '9'
        if len(row) == 2:
            return '1' <= row[0] <= '9' and is_digit(row[1])
        return False

    def tokenize(text):
        tokens = []
        i = 0
        n = len(text)
        while i < n:
            c = text[i]
            if c == ' ':
                i += 1
                continue
            if text.startswith('SUM(', i):
                tokens.append('SUM(')
                i += 4
                continue
            if c in '+-*:()':
                tokens.append(c)
                i += 1
                continue
            if is_digit(c):
                j = i + 1
                while j < n and is_digit(text[j]):
                    j += 1
                tokens.append(text[i:j])
                i = j
                continue
            if 'A' <= c <= 'Z':
                j = i + 1
                if j < n and is_digit(text[j]):
                    k = j
                    while k < n and is_digit(text[k]):
                        k += 1
                    ref = text[i:k]
                    if not is_ref(ref):
                        raise SyntaxError('invalid REF')
                    tokens.append(ref)
                    i = k
                    continue
                raise SyntaxError('invalid REF')
            raise SyntaxError('invalid token')
        return tokens

    def parse_formula(text):
        try:
            tokens = tokenize(text)
        except SyntaxError:
            return None
        pos = 0

        def peek():
            return tokens[pos] if pos < len(tokens) else None

        def parse_expr():
            nonlocal pos
            left = parse_term()
            while pos < len(tokens) and tokens[pos] in ('+', '-'):
                op = tokens[pos]
                pos += 1
                right = parse_term()
                left = ('binop', op, left, right)
            return left

        def parse_term():
            nonlocal pos
            left = parse_unary()
            while pos < len(tokens) and tokens[pos] == '*':
                pos += 1
                right = parse_unary()
                left = ('binop', '*', left, right)
            return left

        def parse_unary():
            nonlocal pos
            if pos < len(tokens) and tokens[pos] == '-':
                pos += 1
                val = parse_unary()
                return ('neg', val)
            return parse_primary()

        def parse_primary():
            nonlocal pos
            tok = peek()
            if tok is None:
                raise SyntaxError('unexpected end')
            if tok.isdigit():
                pos += 1
                return ('num', int(tok))
            if is_ref(tok):
                pos += 1
                return ('ref', tok)
            if tok == 'SUM(':
                pos += 1
                ref1 = peek()
                if not is_ref(ref1):
                    raise SyntaxError('expected REF')
                pos += 1
                if peek() != ':':
                    raise SyntaxError('expected :')
                pos += 1
                ref2 = peek()
                if not is_ref(ref2):
                    raise SyntaxError('expected REF')
                pos += 1
                if peek() != ')':
                    raise SyntaxError('expected )')
                pos += 1
                return ('sum', ref1, ref2)
            if tok == '(':
                pos += 1
                val = parse_expr()
                if peek() != ')':
                    raise SyntaxError('expected )')
                pos += 1
                return val
            raise SyntaxError('unexpected token')

        try:
            ast = parse_expr()
            if pos != len(tokens):
                raise SyntaxError('trailing tokens')
            return ast
        except SyntaxError:
            return None

    def expand_refs(a, b):
        c1 = ord(a[0]) - ord('A')
        r1 = int(a[1:])
        c2 = ord(b[0]) - ord('A')
        r2 = int(b[1:])
        cmin = min(c1, c2)
        cmax = max(c1, c2)
        rmin = min(r1, r2)
        rmax = max(r1, r2)
        out = []
        for r in range(rmin, rmax + 1):
            for c in range(cmin, cmax + 1):
                out.append(chr(ord('A') + c) + str(r))
        return out

    def collect_refs(node):
        kind = node[0]
        if kind == 'num':
            return []
        if kind == 'ref':
            return [node[1]]
        if kind == 'sum':
            return expand_refs(node[1], node[2])
        if kind == 'neg':
            return collect_refs(node[1])
        if kind == 'binop':
            return collect_refs(node[2]) + collect_refs(node[3])
        raise AssertionError('bad node')

    def eval_ast(node, values):
        kind = node[0]
        if kind == 'num':
            return node[1]
        if kind == 'ref':
            return values.get(node[1], 0)
        if kind == 'sum':
            total = 0
            for ref in expand_refs(node[1], node[2]):
                total += values.get(ref, 0)
            return total
        if kind == 'neg':
            return -eval_ast(node[1], values)
        if kind == 'binop':
            left = eval_ast(node[2], values)
            right = eval_ast(node[3], values)
            if node[1] == '+':
                return left + right
            if node[1] == '-':
                return left - right
            if node[1] == '*':
                return left * right
        raise AssertionError('bad node')

    def is_int_literal(raw):
        if not isinstance(raw, str) or raw == '':
            return False
        i = 0
        if raw[0] == '-':
            i = 1
            if i == len(raw):
                return False
        while i < len(raw):
            if not is_digit(raw[i]):
                return False
            i += 1
        return True

    values = {}
    asts = {}
    refs = {}

    for name, raw in cells.items():
        if isinstance(raw, str) and raw.startswith('='):
            ast = parse_formula(raw[1:])
            if ast is None:
                values[name] = '#SYNTAX'
            else:
                asts[name] = ast
                refs[name] = collect_refs(ast)
        else:
            if is_int_literal(raw):
                values[name] = int(raw)
            else:
                values[name] = '#VALUE'

    cycle_set = set()
    for start in list(asts):
        seen = {start}
        stack = [start]
        found = False
        while stack and not found:
            cur = stack.pop()
            for ref in refs.get(cur, ()):
                if ref == start:
                    found = True
                    break
                if ref not in seen:
                    seen.add(ref)
                    stack.append(ref)
        if found:
            cycle_set.add(start)

    for name in cycle_set:
        values[name] = '#CYCLE'

    noncycle = [name for name in asts if name not in cycle_set]
    noncycle_set = set(noncycle)
    indegree = {}
    reverse_adj = {}

    for name in noncycle:
        deps = set(refs[name]) & noncycle_set
        indegree[name] = len(deps)
        for dep in deps:
            reverse_adj.setdefault(dep, set()).add(name)

    queue = [name for name in noncycle if indegree[name] == 0]
    qi = 0
    while qi < len(queue):
        name = queue[qi]
        qi += 1
        first_error = None
        for ref in refs[name]:
            v = values.get(ref, 0)
            if isinstance(v, str):
                first_error = v
                break
        if first_error is not None:
            values[name] = first_error
        else:
            values[name] = eval_ast(asts[name], values)
        for dep in reverse_adj.get(name, ()):
            indegree[dep] -= 1
            if indegree[dep] == 0:
                queue.append(dep)

    return {name: values[name] for name in cells}

from fractions import Fraction


class _Error(Exception):
    pass


def rational_eval(expr):
    if not isinstance(expr, str):
        return 'error'
    try:
        tokens = []
        i = 0
        n = len(expr)
        while i < n:
            ch = expr[i]
            if ch == ' ' or ch == '\t':
                i += 1
                continue
            if '0' <= ch <= '9':
                j = i + 1
                while j < n and '0' <= expr[j] <= '9':
                    j += 1
                tokens.append(expr[i:j])
                i = j
                continue
            if ch in '+-*/^()':
                tokens.append(ch)
                i += 1
                continue
            return 'error'

        pos = 0

        def peek():
            return tokens[pos] if pos < len(tokens) else None

        def advance():
            nonlocal pos
            tok = tokens[pos]
            pos += 1
            return tok

        def parse_expr():
            value = parse_term()
            while peek() == '+' or peek() == '-':
                op = advance()
                rhs = parse_term()
                if op == '+':
                    value = value + rhs
                else:
                    value = value - rhs
            return value

        def parse_term():
            value = parse_unary()
            while peek() == '*' or peek() == '/':
                op = advance()
                rhs = parse_unary()
                if op == '*':
                    value = value * rhs
                else:
                    if rhs == 0:
                        raise _Error()
                    value = value / rhs
            return value

        def parse_unary():
            if peek() == '-':
                advance()
                return -parse_unary()
            return parse_power()

        def parse_power():
            base = parse_atom()
            if peek() == '^':
                advance()
                exponent = parse_unary()
                if exponent.denominator != 1:
                    raise _Error()
                e = exponent.numerator
                if e > 64 or e < -64:
                    raise _Error()
                if e == 0:
                    return Fraction(1)
                if e < 0:
                    if base == 0:
                        raise _Error()
                    return Fraction(1) / (base ** (-e))
                return base ** e
            return base

        def parse_atom():
            tok = peek()
            if tok is None:
                raise _Error()
            if '0' <= tok[0] <= '9':
                advance()
                return Fraction(int(tok))
            if tok == '(':
                advance()
                value = parse_expr()
                if peek() != ')':
                    raise _Error()
                advance()
                return value
            raise _Error()

        if not tokens:
            return 'error'
        result = parse_expr()
        if pos != len(tokens):
            return 'error'
        if result.denominator == 1:
            return str(result.numerator)
        return f'{result.numerator}/{result.denominator}'
    except Exception:
        return 'error'

import re

_NAME_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")

def json_select(doc, path):
    if not isinstance(path, str):
        return None
    if not path.startswith("$"):
        return None
    pos = 1
    values = [doc]
    while pos < len(path):
        step, pos = _parse_step(path, pos)
        if step is None:
            return None
        new_values = []
        for v in values:
            new_values.extend(_apply_step(step, v))
        values = new_values
    return values

def _parse_step(path, i):
    n = len(path)
    if path.startswith("..", i):
        m = _NAME_RE.match(path, i + 2)
        if m is None:
            return None, None
        return ("desc", m.group()), m.end()
    c = path[i]
    if c == '.':
        m = _NAME_RE.match(path, i + 1)
        if m is None:
            return None, None
        return ("key", m.group()), m.end()
    if c == '[':
        if i + 1 >= n:
            return None, None
        nxt = path[i + 1]
        if nxt == '*':
            if i + 2 < n and path[i + 2] == ']':
                return ("star", None), i + 3
            return None, None
        if nxt == "'":
            j = i + 2
            buf = []
            while j < n:
                ch = path[j]
                if ch == "'":
                    if j + 1 < n and path[j + 1] == ']':
                        return ("key", "".join(buf)), j + 2
                    return None, None
                if ch == '\\':
                    if j + 1 >= n:
                        return None, None
                    esc = path[j + 1]
                    if esc == "'":
                        buf.append("'")
                    elif esc == '\\':
                        buf.append('\\')
                    else:
                        return None, None
                    j += 2
                    continue
                buf.append(ch)
                j += 1
            return None, None
        if nxt == '-' or ('0' <= nxt <= '9'):
            j = i + 1
            negative = False
            if path[j] == '-':
                negative = True
                j += 1
            start = j
            while j < n and '0' <= path[j] <= '9':
                j += 1
            digits = path[start:j]
            if not digits:
                return None, None
            if len(digits) > 1 and digits[0] == '0':
                return None, None
            if j >= n or path[j] != ']':
                return None, None
            value = int(digits)
            if negative:
                value = -value
            return ("index", value), j + 1
        return None, None
    return None, None

def _apply_step(step, v):
    kind, arg = step
    if kind == "key":
        if isinstance(v, dict) and arg in v:
            return [v[arg]]
        return []
    if kind == "index":
        if isinstance(v, list):
            length = len(v)
            if arg >= 0:
                if arg < length:
                    return [v[arg]]
            else:
                idx = length + arg
                if 0 <= idx < length:
                    return [v[idx]]
        return []
    if kind == "star":
        if isinstance(v, list):
            return list(v)
        if isinstance(v, dict):
            return list(v.values())
        return []
    if kind == "desc":
        res = []
        stack = [v]
        while stack:
            cur = stack.pop()
            if isinstance(cur, dict):
                if arg in cur:
                    res.append(cur[arg])
                for val in reversed(list(cur.values())):
                    stack.append(val)
            elif isinstance(cur, list):
                for item in reversed(cur):
                    stack.append(item)
        return res
    return []

def csv_parse(text):
    n = len(text)
    pos = 0
    records = []

    while pos < n:
        fields = []
        while True:
            if pos < n and text[pos] == '"':
                p = pos + 1
                field = []
                while True:
                    if p >= n:
                        return None
                    ch = text[p]
                    if ch == '"':
                        if p + 1 < n and text[p + 1] == '"':
                            field.append('"')
                            p += 2
                            continue
                        p += 1
                        break
                    field.append(ch)
                    p += 1
                if p < n:
                    ch = text[p]
                    if ch == ',':
                        pass
                    elif ch == '\n':
                        pass
                    elif ch == '\r' and p + 1 < n and text[p + 1] == '\n':
                        pass
                    else:
                        return None
                pos = p
            else:
                field = []
                p = pos
                while p < n:
                    ch = text[p]
                    if ch == ',' or ch == '\n':
                        break
                    if ch == '\r':
                        if p + 1 < n and text[p + 1] == '\n':
                            break
                        field.append(ch)
                        p += 1
                        continue
                    if ch == '"':
                        return None
                    field.append(ch)
                    p += 1
                pos = p

            fields.append(''.join(field))

            if pos >= n:
                records.append(fields)
                break

            ch = text[pos]
            if ch == ',':
                pos += 1
                continue
            if ch == '\n':
                pos += 1
                records.append(fields)
                break
            if ch == '\r' and pos + 1 < n and text[pos + 1] == '\n':
                pos += 2
                records.append(fields)
                break
            return None

    return records

import heapq

def lex_shortest_path(edges, src, dst):
    for u, v, w in edges:
        if w < 1:
            return None
    if src == dst:
        return [0, [src]]
    adj = {}
    for u, v, w in edges:
        adj.setdefault(u, []).append((v, w))
    dist = {src: 0}
    best = {src: [src]}
    heap = [(0, src)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist.get(u):
            continue
        pu = best[u]
        for v, w in adj.get(u, ()):
            nd = d + w
            cur = dist.get(v)
            if cur is None or nd < cur:
                dist[v] = nd
                best[v] = pu + [v]
                heapq.heappush(heap, (nd, v))
            elif nd == cur:
                cand = pu + [v]
                if cand < best[v]:
                    best[v] = cand
    if dst not in dist:
        return None
    return [dist[dst], best[dst]]

from collections import deque

def grid_portals(grid):
    if not grid:
        return None

    height = len(grid)
    width = len(grid[0])
    for row in grid:
        if len(row) != width:
            return None

    start_count = 0
    exit_count = 0
    start = None
    exit_pos = None
    portals = {}

    for r, row in enumerate(grid):
        for c, ch in enumerate(row):
            if ch == 'S':
                start_count += 1
                start = (r, c)
            elif ch == 'E':
                exit_count += 1
                exit_pos = (r, c)
            elif ch == '.' or ch == '#':
                pass
            elif 'a' <= ch <= 'z':
                portals.setdefault(ch, []).append((r, c))
            else:
                return None

    if start_count != 1 or exit_count != 1:
        return None

    twins = {}
    for positions in portals.values():
        if len(positions) != 2:
            return None
        (r1, c1), (r2, c2) = positions
        twins[(r1, c1)] = (r2, c2)
        twins[(r2, c2)] = (r1, c1)

    dist = {start: 0}
    queue = deque([start])

    while queue:
        r, c = queue.popleft()
        d = dist[(r, c)]

        if (r, c) == exit_pos:
            return d

        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < height and 0 <= nc < width:
                ch = grid[nr][nc]
                if ch == '#':
                    continue
                nd = d + 1
                if 'a' <= ch <= 'z':
                    dest = twins[(nr, nc)]
                else:
                    dest = (nr, nc)
                if dest not in dist or dist[dest] > nd:
                    dist[dest] = nd
                    queue.append(dest)

    return -1

import re

def json_select(doc, path):
    if not isinstance(path, str) or not path.startswith('$'):
        return None
    n = len(path)
    steps = []
    i = 1
    while i < n:
        c = path[i]
        if c == '.':
            j = i + 1
            if j < n and path[j] == '.':
                kind = '..'
                j += 1
            else:
                kind = '.'
            m = re.match(r'[A-Za-z_][A-Za-z0-9_]*', path[j:])
            if not m:
                return None
            name = m.group(0)
            steps.append((kind, name))
            i = j + len(name)
        elif c == '[':
            j = i + 1
            if j >= n:
                return None
            if path[j] == '*':
                if j + 1 >= n or path[j + 1] != ']':
                    return None
                steps.append(('*', None))
                i = j + 2
            elif path[j] == '\'':
                j += 1
                chars = []
                while True:
                    if j >= n:
                        return None
                    ch = path[j]
                    if ch == '\\':
                        if j + 1 >= n:
                            return None
                        nxt = path[j + 1]
                        if nxt == '\'':
                            chars.append('\'')
                            j += 2
                        elif nxt == '\\':
                            chars.append('\\')
                            j += 2
                        else:
                            return None
                    elif ch == '\'':
                        j += 1
                        break
                    else:
                        chars.append(ch)
                        j += 1
                if j >= n or path[j] != ']':
                    return None
                steps.append(('key', ''.join(chars)))
                i = j + 1
            elif path[j] == '-' or ('0' <= path[j] <= '9'):
                j0 = j
                if path[j] == '-':
                    j += 1
                dstart = j
                while j < n and '0' <= path[j] <= '9':
                    j += 1
                if j == dstart:
                    return None
                digits = path[dstart:j]
                if len(digits) > 1 and digits[0] == '0':
                    return None
                if j >= n or path[j] != ']':
                    return None
                num = int(('-' if path[j0] == '-' else '') + digits)
                steps.append(('index', num))
                i = j + 1
            else:
                return None
        else:
            return None

    current = [doc]
    for kind, arg in steps:
        new_current = []
        if kind == '.' or kind == 'key':
            for v in current:
                if isinstance(v, dict) and arg in v:
                    new_current.append(v[arg])
        elif kind == '*':
            for v in current:
                if isinstance(v, list):
                    new_current.extend(v)
                elif isinstance(v, dict):
                    new_current.extend(v.values())
        elif kind == 'index':
            for v in current:
                if isinstance(v, list):
                    idx = arg if arg >= 0 else len(v) + arg
                    if 0 <= idx < len(v):
                        new_current.append(v[idx])
        elif kind == '..':
            for v in current:
                stack = [v]
                while stack:
                    cur = stack.pop()
                    if isinstance(cur, dict):
                        if arg in cur:
                            new_current.append(cur[arg])
                        for val in reversed(list(cur.values())):
                            stack.append(val)
                    elif isinstance(cur, list):
                        for val in reversed(cur):
                            stack.append(val)
        current = new_current
    return current

def bool_minterms(expr):
    if not isinstance(expr, str):
        return None

    class ParseError(Exception):
        pass

    def tokenize(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c == ' ':
                i += 1
                continue
            if 'a' <= c <= 'z':
                j = i + 1
                while j < n and 'a' <= s[j] <= 'z':
                    j += 1
                tokens.append(('var', s[i:j]))
                i = j
                continue
            if '0' <= c <= '9':
                j = i + 1
                while j < n and '0' <= s[j] <= '9':
                    j += 1
                run = s[i:j]
                if run == '0':
                    tokens.append(('const', False))
                elif run == '1':
                    tokens.append(('const', True))
                else:
                    return None
                i = j
                continue
            if c == '!':
                tokens.append(('op', '!'))
                i += 1
                continue
            if c == '&':
                tokens.append(('op', '&'))
                i += 1
                continue
            if c == '^':
                tokens.append(('op', '^'))
                i += 1
                continue
            if c == '|':
                tokens.append(('op', '|'))
                i += 1
                continue
            if c == '-':
                if i + 1 < n and s[i + 1] == '>':
                    tokens.append(('op', '->'))
                    i += 2
                    continue
                return None
            if c == '(':
                tokens.append(('lparen',))
                i += 1
                continue
            if c == ')':
                tokens.append(('rparen',))
                i += 1
                continue
            return None
        return tokens

    tokens = tokenize(expr)
    if tokens is None or not tokens:
        return None

    PRECEDENCE = {'->': 1, '|': 2, '^': 3, '&': 4}

    def parse_prefix(pos):
        if pos >= len(tokens):
            raise ParseError
        tok = tokens[pos]
        if tok[0] == 'op' and tok[1] == '!':
            node, pos = parse_prefix(pos + 1)
            return ('!', node), pos
        if tok[0] == 'var':
            return ('var', tok[1]), pos + 1
        if tok[0] == 'const':
            return ('const', tok[1]), pos + 1
        if tok[0] == 'lparen':
            node, pos = parse_expr(pos + 1, 0)
            if pos >= len(tokens) or tokens[pos][0] != 'rparen':
                raise ParseError
            return node, pos + 1
        raise ParseError

    def parse_expr(pos, min_prec):
        node, pos = parse_prefix(pos)
        while pos < len(tokens):
            tok = tokens[pos]
            if tok[0] != 'op':
                break
            op = tok[1]
            prec = PRECEDENCE.get(op)
            if prec is None or prec < min_prec:
                break
            pos += 1
            if op == '->':
                right, pos = parse_expr(pos, prec)
                node = ('->', node, right)
            else:
                right, pos = parse_expr(pos, prec + 1)
                node = (op, node, right)
        return node, pos

    try:
        ast, pos = parse_expr(0, 0)
        if pos != len(tokens):
            return None
    except ParseError:
        return None

    def collect_vars(node, out):
        if node[0] == 'var':
            out.add(node[1])
        elif node[0] == 'const':
            pass
        elif node[0] == '!':
            collect_vars(node[1], out)
        else:
            collect_vars(node[1], out)
            collect_vars(node[2], out)

    var_set = set()
    collect_vars(ast, var_set)
    variables = sorted(var_set)

    def evaluate(node, values):
        t = node[0]
        if t == 'var':
            return values[node[1]]
        if t == 'const':
            return node[1]
        if t == '!':
            return not evaluate(node[1], values)
        if t == '&':
            return evaluate(node[1], values) and evaluate(node[2], values)
        if t == '^':
            return evaluate(node[1], values) != evaluate(node[2], values)
        if t == '|':
            return evaluate(node[1], values) or evaluate(node[2], values)
        if t == '->':
            return (not evaluate(node[1], values)) or evaluate(node[2], values)
        raise ParseError

    n = len(variables)
    minterms = []
    for i in range(1 << n):
        values = {}
        for j, v in enumerate(variables):
            values[v] = bool((i >> (n - 1 - j)) & 1)
        if evaluate(ast, values):
            minterms.append(i)
    return [variables, minterms]

def league_table(matches):
    stats = {}
    valid = []
    for match in matches:
        home, away, home_goals, away_goals = match
        if home == away:
            continue
        if home_goals < 0 or away_goals < 0:
            continue
        valid.append((home, away, home_goals, away_goals))
        for team in (home, away):
            if team not in stats:
                stats[team] = {"played": 0, "won": 0, "drawn": 0, "lost": 0,
                               "gf": 0, "ga": 0, "points": 0}
        h = stats[home]
        a = stats[away]
        h["played"] += 1
        a["played"] += 1
        h["gf"] += home_goals
        h["ga"] += away_goals
        a["gf"] += away_goals
        a["ga"] += home_goals
        if home_goals > away_goals:
            h["won"] += 1
            h["points"] += 3
            a["lost"] += 1
        elif home_goals < away_goals:
            a["won"] += 1
            a["points"] += 3
            h["lost"] += 1
        else:
            h["drawn"] += 1
            h["points"] += 1
            a["drawn"] += 1
            a["points"] += 1

    groups = {}
    for team, s in stats.items():
        groups.setdefault(s["points"], []).append(team)

    h2h = {}
    for points, group in groups.items():
        group_set = set(group)
        h2h_pts = {t: 0 for t in group}
        h2h_gd = {t: 0 for t in group}
        for home, away, hg, ag in valid:
            if home in group_set and away in group_set:
                if hg > ag:
                    h2h_pts[home] += 3
                    h2h_gd[home] += hg - ag
                    h2h_gd[away] += ag - hg
                elif hg < ag:
                    h2h_pts[away] += 3
                    h2h_gd[away] += ag - hg
                    h2h_gd[home] += hg - ag
                else:
                    h2h_pts[home] += 1
                    h2h_pts[away] += 1
        for t in group:
            h2h[t] = (h2h_pts[t], h2h_gd[t])

    ordered = sorted(
        stats,
        key=lambda t: (
            -stats[t]["points"],
            -h2h[t][0],
            -h2h[t][1],
            -(stats[t]["gf"] - stats[t]["ga"]),
            -stats[t]["gf"],
            t,
        ),
    )

    return [
        [t, stats[t]["played"], stats[t]["won"], stats[t]["drawn"],
         stats[t]["lost"], stats[t]["gf"], stats[t]["ga"], stats[t]["points"]]
        for t in ordered
    ]

import heapq

def lex_shortest_path(edges, src, dst):
    for u, v, w in edges:
        if w < 1:
            return None
    if src == dst:
        return [0, [src]]
    adj = {}
    for u, v, w in edges:
        adj.setdefault(u, []).append((v, w))
    dist = {src: 0}
    path = {src: [src]}
    heap = [(0, src)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist.get(u):
            continue
        if u == dst:
            return [d, path[u]]
        for v, w in adj.get(u, ()):
            nd = d + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd
                path[v] = path[u] + [v]
                heapq.heappush(heap, (nd, v))
            elif nd == dist.get(v):
                cand = path[u] + [v]
                if cand < path[v]:
                    path[v] = cand
    return None

def spreadsheet_eval(cells):
    def is_int_literal(raw):
        if not raw:
            return False
        i = 0
        if raw[0] == '-':
            i = 1
        if i >= len(raw):
            return False
        for ch in raw[i:]:
            if '0' <= ch <= '9':
                continue
            return False
        return True

    def expand(ref1, ref2):
        row1 = int(ref1[1:])
        row2 = int(ref2[1:])
        top = row1 if row1 < row2 else row2
        bottom = row1 if row1 > row2 else row2
        left = ord(ref1[0])
        right = ord(ref2[0])
        if left > right:
            left, right = right, left
        result = []
        for row in range(top, bottom + 1):
            for col in range(left, right + 1):
                result.append(chr(col) + str(row))
        return result

    def eval_node(node, get_value):
        kind = node[0]
        if kind == 'int':
            return node[1]
        if kind == 'ref':
            return get_value(node[1])
        if kind == 'sum':
            return sum(get_value(name) for name in expand(node[1], node[2]))
        if kind == 'neg':
            return -eval_node(node[1], get_value)
        if kind == 'bin':
            op = node[1]
            left = eval_node(node[2], get_value)
            right = eval_node(node[3], get_value)
            if op == '+':
                return left + right
            if op == '-':
                return left - right
            return left * right
        raise AssertionError('unknown node')

    def parse_formula(formula):
        s = formula
        n = len(s)

        def skip_spaces(i):
            while i < n and s[i] == ' ':
                i += 1
            return i

        def parse_ref_name(i):
            i = skip_spaces(i)
            if i >= n or not ('A' <= s[i] <= 'Z'):
                raise SyntaxError('expected REF')
            letter = s[i]
            i += 1
            start = i
            while i < n and '0' <= s[i] <= '9':
                i += 1
            digits = s[start:i]
            if not digits:
                raise SyntaxError('expected row')
            row = int(digits)
            if row < 1 or row > 99:
                raise SyntaxError('bad row')
            if digits != str(row):
                raise SyntaxError('bad row')
            return letter + digits, i

        def parse_primary(i):
            i = skip_spaces(i)
            if i >= n:
                raise SyntaxError('unexpected end')
            ch = s[i]
            if ch == '(':
                i += 1
                node, refs, i = parse_expr(i)
                i = skip_spaces(i)
                if i >= n or s[i] != ')':
                    raise SyntaxError('expected )')
                i += 1
                return node, refs, i
            if '0' <= ch <= '9':
                start = i
                while i < n and '0' <= s[i] <= '9':
                    i += 1
                digits = s[start:i]
                return ('int', int(digits)), [], i
            if ch == 'S' and s.startswith('SUM(', i):
                i += 4
                ref1, i = parse_ref_name(i)
                i = skip_spaces(i)
                if i >= n or s[i] != ':':
                    raise SyntaxError('expected :')
                i += 1
                ref2, i = parse_ref_name(i)
                i = skip_spaces(i)
                if i >= n or s[i] != ')':
                    raise SyntaxError('expected )')
                i += 1
                return ('sum', ref1, ref2), expand(ref1, ref2), i
            if 'A' <= ch <= 'Z':
                name, i = parse_ref_name(i)
                return ('ref', name), [name], i
            raise SyntaxError('unexpected token')

        def parse_unary(i):
            i = skip_spaces(i)
            if i < n and s[i] == '-':
                i += 1
                child, refs, i = parse_unary(i)
                return ('neg', child), refs, i
            return parse_primary(i)

        def parse_term(i):
            left, refs_left, i = parse_unary(i)
            refs = refs_left
            while True:
                i = skip_spaces(i)
                if i < n and s[i] == '*':
                    i += 1
                    right, refs_right, i = parse_unary(i)
                    refs = refs + refs_right
                    left = ('bin', '*', left, right)
                    continue
                break
            return left, refs, i

        def parse_expr(i):
            left, refs_left, i = parse_term(i)
            refs = refs_left
            while True:
                i = skip_spaces(i)
                if i < n and s[i] in '+-':
                    op = s[i]
                    i += 1
                    right, refs_right, i = parse_term(i)
                    refs = refs + refs_right
                    left = ('bin', op, left, right)
                    continue
                break
            return left, refs, i

        node, refs, i = parse_expr(0)
        i = skip_spaces(i)
        if i != n:
            raise SyntaxError('trailing garbage')
        return node, refs

    records = {}
    values = {}
    for key, raw in cells.items():
        if not raw.startswith('='):
            if is_int_literal(raw):
                values[key] = int(raw)
            else:
                values[key] = '#VALUE'
            records[key] = {'kind': 'literal', 'value': values[key]}
        else:
            try:
                ast, refs = parse_formula(raw[1:])
            except SyntaxError:
                records[key] = {'kind': 'formula', 'parse_error': True}
                values[key] = '#SYNTAX'
            else:
                records[key] = {'kind': 'formula', 'ast': ast, 'refs': refs, 'cycle': False}

    formula_names = [key for key, rec in records.items() if rec['kind'] == 'formula' and 'ast' in rec]
    edges = {key: set() for key in formula_names}
    for key in formula_names:
        for ref in records[key]['refs']:
            if ref in edges:
                edges[key].add(ref)

    def reaches_self(start):
        seen = {start}
        stack = [start]
        while stack:
            node = stack.pop()
            for nxt in edges.get(node, ()):
                if nxt == start:
                    return True
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
        return False

    cycle_names = set()
    for key in formula_names:
        if reaches_self(key):
            cycle_names.add(key)

    for key in cycle_names:
        records[key]['cycle'] = True
        values[key] = '#CYCLE'

    memo = {}

    def ref_value(ref):
        if ref in memo:
            return memo[ref]
        rec = records.get(ref)
        if rec is None:
            return 0
        if rec['kind'] == 'literal':
            return rec['value']
        if 'ast' not in rec:
            return '#SYNTAX'
        if rec.get('cycle'):
            return '#CYCLE'
        value = compute_formula(ref)
        memo[ref] = value
        return value

    def compute_formula(key):
        rec = records[key]
        for ref in rec['refs']:
            value = ref_value(ref)
            if isinstance(value, str):
                return value
        return eval_node(rec['ast'], ref_value)

    for key in formula_names:
        if key not in cycle_names:
            value = compute_formula(key)
            memo[key] = value
            values[key] = value

    return values

def token_bucket(capacity, refill_ms, requests):
    if capacity < 1 or refill_ms < 1:
        return None

    tokens = capacity
    mark = 0
    accepted = []
    last_t = None

    for i, req in enumerate(requests):
        t, cost = req
        if cost < 1 or t < 0:
            continue
        if last_t is not None and t < last_t:
            continue

        last_t = t

        if tokens < capacity:
            g = (t - mark) // refill_ms
            if tokens + g >= capacity:
                tokens = capacity
            else:
                tokens += g
                mark += g * refill_ms

        if tokens == capacity:
            mark = t

        if cost <= tokens:
            tokens -= cost
            accepted.append(i)

    return accepted

import re
import sys


def _tokenize(s):
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == ' ':
            i += 1
            continue
        if s.startswith('SUM(', i):
            tokens.append(('SUM', 'SUM('))
            i += 4
            continue
        if '0' <= c <= '9':
            j = i
            while j < n and '0' <= s[j] <= '9':
                j += 1
            tokens.append(('NUM', int(s[i:j])))
            i = j
            continue
        if 'A' <= c <= 'Z':
            j = i + 1
            k = j
            while k < n and '0' <= s[k] <= '9':
                k += 1
            row = s[j:k]
            if not row or row[0] == '0':
                return None
            if not (1 <= int(row) <= 99):
                return None
            tokens.append(('REF', c + row))
            i = k
            continue
        if c in '+-*():':
            tokens.append((c, c))
            i += 1
            continue
        return None
    return tokens


def _parse_formula(s):
    tokens = _tokenize(s)
    if not tokens:
        return None
    n = len(tokens)
    pos = 0

    def peek():
        if pos < n:
            return tokens[pos][0]
        return None

    def next_tok():
        nonlocal pos
        t = tokens[pos]
        pos += 1
        return t

    def parse_expr():
        node = parse_term()
        while peek() == '+' or peek() == '-':
            op = next_tok()[0]
            rhs = parse_term()
            node = (op, node, rhs)
        return node

    def parse_term():
        node = parse_unary()
        while peek() == '*':
            next_tok()
            rhs = parse_unary()
            node = ('*', node, rhs)
        return node

    def parse_unary():
        if peek() == '-':
            next_tok()
            return ('neg', parse_unary())
        return parse_primary()

    def parse_ref():
        if peek() != 'REF':
            raise SyntaxError
        return next_tok()[1]

    def parse_primary():
        p = peek()
        if p == 'NUM':
            return ('num', next_tok()[1])
        if p == 'REF':
            return ('ref', next_tok()[1])
        if p == 'SUM':
            next_tok()
            a = parse_ref()
            if peek() != ':':
                raise SyntaxError
            next_tok()
            b = parse_ref()
            if peek() != ')':
                raise SyntaxError
            next_tok()
            return ('sum', a, b)
        if p == '(':
            next_tok()
            node = parse_expr()
            if peek() != ')':
                raise SyntaxError
            next_tok()
            return node
        raise SyntaxError

    try:
        node = parse_expr()
        if pos != n:
            return None
        return node
    except Exception:
        return None


def _expand_range(a, b):
    col1 = ord(a[0])
    row1 = int(a[1:])
    col2 = ord(b[0])
    row2 = int(b[1:])
    out = []
    for r in range(min(row1, row2), max(row1, row2) + 1):
        for c in range(min(col1, col2), max(col1, col2) + 1):
            out.append(chr(c) + str(r))
    return out


def _collect_refs(node):
    tag = node[0]
    if tag == 'ref':
        return [node[1]]
    if tag == 'num':
        return []
    if tag == 'neg':
        return _collect_refs(node[1])
    if tag == 'sum':
        return _expand_range(node[1], node[2])
    return _collect_refs(node[1]) + _collect_refs(node[2])


def _eval_ast(node, get_value):
    tag = node[0]
    if tag == 'num':
        return node[1]
    if tag == 'ref':
        return get_value(node[1])
    if tag == 'neg':
        return -_eval_ast(node[1], get_value)
    if tag == 'sum':
        total = 0
        for cell in _expand_range(node[1], node[2]):
            total += get_value(cell)
        return total
    left = _eval_ast(node[1], get_value)
    right = _eval_ast(node[2], get_value)
    if tag == '+':
        return left + right
    if tag == '-':
        return left - right
    return left * right


def spreadsheet_eval(cells):
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 100000))
    is_formula = {}
    ast = {}
    refs = {}
    literal_value = {}

    for key, raw in cells.items():
        if raw.startswith('='):
            is_formula[key] = True
            node = _parse_formula(raw[1:])
            ast[key] = node
            refs[key] = _collect_refs(node) if node is not None else []
        else:
            is_formula[key] = False
            if re.fullmatch(r'-?[0-9]+', raw):
                literal_value[key] = int(raw)
            else:
                literal_value[key] = '#VALUE'
            refs[key] = []

    def can_reach_self(k):
        stack = list(refs[k])
        seen = set()
        while stack:
            cur = stack.pop()
            if cur == k:
                return True
            if cur in seen:
                continue
            seen.add(cur)
            for r in refs.get(cur, []):
                if r not in seen:
                    stack.append(r)
        return False

    in_cycle = set()
    for key in cells:
        if is_formula[key] and ast[key] is not None:
            if can_reach_self(key):
                in_cycle.add(key)

    values = {}

    def get_value(cell):
        if cell in values:
            return values[cell]
        if cell not in cells:
            return 0
        if not is_formula[cell]:
            v = literal_value[cell]
            values[cell] = v
            return v
        if ast[cell] is None:
            v = '#SYNTAX'
            values[cell] = v
            return v
        if cell in in_cycle:
            v = '#CYCLE'
            values[cell] = v
            return v
        for r in refs[cell]:
            v = get_value(r)
            if isinstance(v, str):
                values[cell] = v
                return v
        v = _eval_ast(ast[cell], get_value)
        values[cell] = v
        return v

    result = {}
    for key in cells:
        result[key] = get_value(key)
    return result

def league_table(matches):
    valid = []
    for match in matches:
        home, away, home_goals, away_goals = match
        if home == away:
            continue
        if home_goals < 0 or away_goals < 0:
            continue
        valid.append((home, away, home_goals, away_goals))

    stats = {}
    for home, away, home_goals, away_goals in valid:
        for team, goals_for, goals_against in ((home, home_goals, away_goals),
                                               (away, away_goals, home_goals)):
            s = stats.get(team)
            if s is None:
                s = [0, 0, 0, 0, 0, 0, 0]
                stats[team] = s
            s[0] += 1
            s[4] += goals_for
            s[5] += goals_against

        if home_goals > away_goals:
            stats[home][1] += 1
            stats[home][6] += 3
            stats[away][3] += 1
        elif home_goals < away_goals:
            stats[away][1] += 1
            stats[away][6] += 3
            stats[home][3] += 1
        else:
            stats[home][2] += 1
            stats[away][2] += 1
            stats[home][6] += 1
            stats[away][6] += 1

    groups = {}
    for name, s in stats.items():
        groups.setdefault(s[6], []).append(name)

    h2h_points = {}
    h2h_gd = {}
    for name, s in stats.items():
        group = set(groups[s[6]])
        pts = 0
        gf = 0
        ga = 0
        for home, away, home_goals, away_goals in valid:
            if home not in group or away not in group:
                continue
            if home == name:
                gf += home_goals
                ga += away_goals
                if home_goals > away_goals:
                    pts += 3
                elif home_goals == away_goals:
                    pts += 1
            elif away == name:
                gf += away_goals
                ga += home_goals
                if away_goals > home_goals:
                    pts += 3
                elif away_goals == home_goals:
                    pts += 1
        h2h_points[name] = pts
        h2h_gd[name] = gf - ga

    def sort_key(name):
        s = stats[name]
        overall_gd = s[4] - s[5]
        return (-s[6], -h2h_points[name], -h2h_gd[name],
                -overall_gd, -s[4], name)

    ranked = sorted(stats, key=sort_key)

    rows = []
    for name in ranked:
        played, won, drawn, lost, gf, ga, points = stats[name]
        rows.append([name, played, won, drawn, lost, gf, ga, points])
    return rows

import re


_REF_PREFIX = re.compile(r'[A-Z](?:[1-9][0-9]|[1-9])')
_REF_FULL = re.compile(r'[A-Z](?:[1-9][0-9]|[1-9])')
_INT_FULL = re.compile(r'[0-9]+')


def _tokenize(s):
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == ' ':
            i += 1
            continue
        if s.startswith('SUM(', i):
            tokens.append('SUM(')
            i += 4
            continue
        if c in '+-*():':
            tokens.append(c)
            i += 1
            continue
        if '0' <= c <= '9':
            j = i
            while j < n and '0' <= s[j] <= '9':
                j += 1
            tokens.append(s[i:j])
            i = j
            continue
        if 'A' <= c <= 'Z':
            m = _REF_PREFIX.match(s, i)
            if m is not None:
                tokens.append(m.group())
                i = m.end()
                continue
            raise ValueError('invalid reference')
        raise ValueError('invalid character')
    return tokens


class _Parser:
    __slots__ = ('tokens', 'pos')

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def next(self):
        t = self.tokens[self.pos]
        self.pos += 1
        return t

    def parse_expr(self):
        node = self.parse_term()
        while self.peek() == '+' or self.peek() == '-':
            op = self.next()
            right = self.parse_term()
            node = ('binop', op, node, right)
        return node

    def parse_term(self):
        node = self.parse_unary()
        while self.peek() == '*':
            self.next()
            right = self.parse_unary()
            node = ('binop', '*', node, right)
        return node

    def parse_unary(self):
        if self.peek() == '-':
            self.next()
            return ('neg', self.parse_unary())
        return self.parse_primary()

    def parse_primary(self):
        t = self.next()
        if t == '(':
            node = self.parse_expr()
            if self.next() != ')':
                raise ValueError('expected )')
            return node
        if t == 'SUM(':
            r1 = self.next()
            if not _REF_FULL.fullmatch(r1):
                raise ValueError('bad ref')
            if self.next() != ':':
                raise ValueError('expected :')
            r2 = self.next()
            if not _REF_FULL.fullmatch(r2):
                raise ValueError('bad ref')
            if self.next() != ')':
                raise ValueError('expected )')
            return ('sum', r1, r2)
        if _REF_FULL.fullmatch(t):
            return ('ref', t)
        if _INT_FULL.fullmatch(t):
            return ('int', int(t))
        raise ValueError('bad primary')


def _parse_formula(s):
    try:
        tokens = _tokenize(s)
        parser = _Parser(tokens)
        node = parser.parse_expr()
        if parser.peek() is not None:
            return None
        return node
    except Exception:
        return None


def _sum_refs(r1, r2):
    col1 = ord(r1[0]) - 65
    row1 = int(r1[1:])
    col2 = ord(r2[0]) - 65
    row2 = int(r2[1:])
    refs = []
    for row in range(min(row1, row2), max(row1, row2) + 1):
        for col in range(min(col1, col2), max(col1, col2) + 1):
            refs.append(chr(65 + col) + str(row))
    return refs


def _refs_of(node):
    t = node[0]
    if t == 'int':
        return []
    if t == 'ref':
        return [node[1]]
    if t == 'neg':
        return _refs_of(node[1])
    if t == 'binop':
        return _refs_of(node[2]) + _refs_of(node[3])
    return _sum_refs(node[1], node[2])


def _eval_ast(node, cell_value):
    t = node[0]
    if t == 'int':
        return node[1]
    if t == 'ref':
        return cell_value(node[1])
    if t == 'neg':
        return -_eval_ast(node[1], cell_value)
    if t == 'binop':
        left = _eval_ast(node[2], cell_value)
        right = _eval_ast(node[3], cell_value)
        op = node[1]
        if op == '+':
            return left + right
        if op == '-':
            return left - right
        return left * right
    total = 0
    for r in _sum_refs(node[1], node[2]):
        total += cell_value(r)
    return total


def _reaches_self(start, refs_map, formula_keys):
    stack = [r for r in refs_map[start] if r in formula_keys]
    seen = set()
    while stack:
        node = stack.pop()
        if node == start:
            return True
        if node in seen:
            continue
        seen.add(node)
        for r in refs_map[node]:
            if r in formula_keys:
                stack.append(r)
    return False


def spreadsheet_eval(cells):
    literal_values = {}
    formulas = {}
    for key, raw in cells.items():
        if not isinstance(raw, str):
            literal_values[key] = '#VALUE'
            continue
        if not raw.startswith('='):
            if re.fullmatch(r'-?[0-9]+', raw):
                literal_values[key] = int(raw)
            else:
                literal_values[key] = '#VALUE'
            continue
        ast = _parse_formula(raw[1:])
        if ast is None:
            literal_values[key] = '#SYNTAX'
        else:
            formulas[key] = ast

    refs_map = {}
    for key, ast in formulas.items():
        refs_map[key] = _refs_of(ast)

    formula_keys = set(formulas)
    cycle = set()
    for key in formulas:
        if _reaches_self(key, refs_map, formula_keys):
            cycle.add(key)

    values = dict(literal_values)
    for key in formulas:
        if key in cycle:
            values[key] = '#CYCLE'

    def cell_value(name):
        v = values.get(name)
        if v is not None:
            return v
        if name not in cells:
            return 0
        ast = formulas[name]
        for r in refs_map[name]:
            rv = cell_value(r)
            if isinstance(rv, str):
                values[name] = rv
                return rv
        v = _eval_ast(ast, cell_value)
        values[name] = v
        return v

    for key in formulas:
        if key not in cycle:
            cell_value(key)

    return {key: values[key] for key in cells}

def common_free_slots(calendars, day_start, day_end, min_len):
    if min_len < 1:
        return None

    def parse_time(t):
        if not isinstance(t, str) or len(t) != 5 or t[2] != ':':
            return None
        hh = t[:2]
        mm = t[3:]
        for ch in hh + mm:
            if ch < '0' or ch > '9':
                return None
        h = int(hh)
        m = int(mm)
        if h == 24:
            return 1440 if m == 0 else None
        if h > 23 or m > 59:
            return None
        return h * 60 + m

    ds = parse_time(day_start)
    de = parse_time(day_end)
    if ds is None or de is None:
        return None

    busy_intervals = []
    for cal in calendars:
        offset, busy = cal
        for s, e in busy:
            sm = parse_time(s)
            em = parse_time(e)
            if sm is None or em is None:
                return None
            busy_intervals.append((offset, sm, em))

    if de <= ds:
        return []

    def fmt(m):
        if m == 1440:
            return '24:00'
        return f'{m // 60:02d}:{m % 60:02d}'

    intervals = []
    for offset, sm, em in busy_intervals:
        if em <= sm:
            continue
        a = sm - offset
        b = em - offset
        if a < ds:
            a = ds
        if b > de:
            b = de
        if b > a:
            intervals.append((a, b))

    intervals.sort(key=lambda iv: iv[0])
    merged = []
    for a, b in intervals:
        if merged and a <= merged[-1][1]:
            if b > merged[-1][1]:
                merged[-1][1] = b
        else:
            merged.append([a, b])

    slots = []
    cur = ds
    for a, b in merged:
        if a > cur:
            if a - cur >= min_len:
                slots.append([fmt(cur), fmt(a)])
        if b > cur:
            cur = b
    if de > cur and de - cur >= min_len:
        slots.append([fmt(cur), fmt(de)])
    return slots

def poly_expand(expr):
    if not isinstance(expr, str):
        return None
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c == ' ':
            i += 1
            continue
        if '0' <= c <= '9':
            j = i
            while j < n and '0' <= expr[j] <= '9':
                j += 1
            tokens.append(('int', int(expr[i:j])))
            i = j
            continue
        if c in '+-*^()x':
            tokens.append(c)
            i += 1
            continue
        return None

    idx = 0

    def peek():
        return tokens[idx] if idx < len(tokens) else None

    def bump():
        nonlocal idx
        tok = tokens[idx]
        idx += 1
        return tok

    def add_polys(a, b):
        res = dict(a)
        for d, c in b.items():
            if c == 0:
                continue
            res[d] = res.get(d, 0) + c
            if res[d] == 0:
                del res[d]
        return res

    def mul_polys(a, b):
        res = {}
        for da, ca in a.items():
            if ca == 0:
                continue
            for db, cb in b.items():
                if cb == 0:
                    continue
                d = da + db
                res[d] = res.get(d, 0) + ca * cb
        return {d: c for d, c in res.items() if c != 0}

    def pow_poly(p, e):
        if e == 0:
            return {0: 1}
        res = {0: 1}
        for _ in range(e):
            res = mul_polys(res, p)
            if not res:
                return {}
        return res

    def negate_poly(p):
        return {d: -c for d, c in p.items() if c != 0}

    def parse_expr():
        p = parse_term()
        if p is None:
            return None
        while peek() == '+' or peek() == '-':
            op = bump()
            t = parse_term()
            if t is None:
                return None
            if op == '+':
                p = add_polys(p, t)
            else:
                p = add_polys(p, negate_poly(t))
        return p

    def parse_term():
        f = parse_factor()
        if f is None:
            return None
        while peek() == '*':
            bump()
            g = parse_factor()
            if g is None:
                return None
            f = mul_polys(f, g)
        return f

    def parse_factor():
        sign = 1
        while peek() == '-':
            bump()
            sign = -sign
        base = parse_base()
        if base is None:
            return None
        if peek() == '^':
            bump()
            tok = peek()
            if not (isinstance(tok, tuple) and tok[0] == 'int'):
                return None
            bump()
            exp = tok[1]
            if exp > 20:
                return None
            base = pow_poly(base, exp)
        if sign == -1:
            base = negate_poly(base)
        return base

    def parse_base():
        tok = peek()
        if tok is None:
            return None
        if isinstance(tok, tuple) and tok[0] == 'int':
            bump()
            return {0: tok[1]}
        if tok == 'x':
            bump()
            return {1: 1}
        if tok == '(':
            bump()
            e = parse_expr()
            if e is None:
                return None
            if peek() != ')':
                return None
            bump()
            return e
        return None

    result = parse_expr()
    if result is None:
        return None
    if idx != len(tokens):
        return None

    terms = [(d, c) for d, c in result.items() if c != 0]
    if not terms:
        return '0'
    terms.sort(key=lambda item: -item[0])
    parts = []
    first = True
    for d, c in terms:
        ac = abs(c)
        if d == 0:
            text = str(ac)
        else:
            text = ''
            if ac != 1:
                text += str(ac)
            text += 'x'
            if d > 1:
                text += '^' + str(d)
        if first:
            parts.append(('-' if c < 0 else '') + text)
            first = False
        else:
            parts.append(('-' if c < 0 else '+') + text)
    return ''.join(parts)

from collections import deque

def grid_portals(grid):
    if not isinstance(grid, list) or not grid:
        return None
    if not all(isinstance(row, str) for row in grid):
        return None
    height = len(grid)
    width = len(grid[0])
    if any(len(row) != width for row in grid):
        return None

    start = None
    exit_ = None
    portals = {}
    for r, row in enumerate(grid):
        for c, ch in enumerate(row):
            if ch == 'S':
                if start is not None:
                    return None
                start = (r, c)
            elif ch == 'E':
                if exit_ is not None:
                    return None
                exit_ = (r, c)
            elif ch == '.' or ch == '#':
                pass
            elif 'a' <= ch <= 'z':
                portals.setdefault(ch, []).append((r, c))
            else:
                return None

    if start is None or exit_ is None:
        return None
    for cells in portals.values():
        if len(cells) != 2:
            return None

    twin = {}
    for cells in portals.values():
        (r1, c1), (r2, c2) = cells
        twin[(r1, c1)] = (r2, c2)
        twin[(r2, c2)] = (r1, c1)

    queue = deque([start])
    distance = {start: 0}
    while queue:
        r, c = queue.popleft()
        d = distance[(r, c)]
        if (r, c) == exit_:
            return d
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < height and 0 <= nc < width:
                ch = grid[nr][nc]
                if ch == '#':
                    continue
                nxt = (nr, nc)
                if ch in portals:
                    nxt = twin[nxt]
                if nxt not in distance:
                    distance[nxt] = d + 1
                    queue.append(nxt)
    return -1

def json_select(doc, path):
    if not isinstance(path, str):
        return None
    n = len(path)
    if n == 0 or path[0] != '$':
        return None

    def _name_at(i):
        if i >= n:
            return None, i
        c = path[i]
        if not ('A' <= c <= 'Z' or 'a' <= c <= 'z' or c == '_'):
            return None, i
        j = i + 1
        while j < n:
            ch = path[j]
            if 'A' <= ch <= 'Z' or 'a' <= ch <= 'z' or '0' <= ch <= '9' or ch == '_':
                j += 1
            else:
                break
        return path[i:j], j

    steps = []
    i = 1
    while i < n:
        c = path[i]
        if c == '.':
            if path.startswith('..', i):
                name, j = _name_at(i + 2)
                if name is None:
                    return None
                steps.append(('recurse', name))
                i = j
            else:
                name, j = _name_at(i + 1)
                if name is None:
                    return None
                steps.append(('key', name))
                i = j
        elif c == '[':
            if path.startswith("['", i):
                j = i + 2
                chars = []
                while True:
                    if j >= n:
                        return None
                    ch = path[j]
                    if ch == '\\':
                        if j + 1 >= n:
                            return None
                        nxt = path[j + 1]
                        if nxt == "'":
                            chars.append("'")
                            j += 2
                        elif nxt == '\\':
                            chars.append('\\')
                            j += 2
                        else:
                            return None
                    elif ch == "'":
                        break
                    else:
                        chars.append(ch)
                        j += 1
                if j + 1 >= n or path[j + 1] != ']':
                    return None
                steps.append(('key', ''.join(chars)))
                i = j + 2
            elif path.startswith('[*]', i):
                steps.append(('star',))
                i += 3
            else:
                j = i + 1
                neg = False
                if j < n and path[j] == '-':
                    neg = True
                    j += 1
                dstart = j
                while j < n and '0' <= path[j] <= '9':
                    j += 1
                digits = path[dstart:j]
                if digits == '':
                    return None
                if len(digits) > 1 and digits[0] == '0':
                    return None
                if j >= n or path[j] != ']':
                    return None
                try:
                    num = int(digits)
                except ValueError:
                    num = None
                if num is not None and neg:
                    num = -num
                steps.append(('index', num))
                i = j + 1
        else:
            return None

    def _collect(value, name, out):
        stack = [value]
        while stack:
            node = stack.pop()
            if isinstance(node, dict):
                if name in node:
                    out.append(node[name])
                for key in reversed(list(node)):
                    stack.append(node[key])
            elif isinstance(node, list):
                for item in reversed(node):
                    stack.append(item)

    current = [doc]
    for step in steps:
        kind = step[0]
        if kind == 'key':
            name = step[1]
            new = []
            for v in current:
                if isinstance(v, dict) and name in v:
                    new.append(v[name])
            current = new
        elif kind == 'index':
            num = step[1]
            new = []
            if num is not None:
                for v in current:
                    if isinstance(v, list):
                        idx = num if num >= 0 else len(v) + num
                        if 0 <= idx < len(v):
                            new.append(v[idx])
            current = new
        elif kind == 'star':
            new = []
            for v in current:
                if isinstance(v, list):
                    new.extend(v)
                elif isinstance(v, dict):
                    new.extend(v.values())
            current = new
        else:  # recurse
            name = step[1]
            new = []
            for v in current:
                _collect(v, name, new)
            current = new
    return current

def common_free_slots(calendars, day_start, day_end, min_len):
    try:
        if min_len < 1:
            return None
    except TypeError:
        return None

    def parse_time(s):
        if not isinstance(s, str):
            return None
        if s == '24:00':
            return 1440
        if len(s) != 5 or s[2] != ':':
            return None
        hh = s[:2]
        mm = s[3:]
        for c in hh + mm:
            if c < '0' or c > '9':
                return None
        h = int(hh)
        m = int(mm)
        if h > 23 or m > 59:
            return None
        return h * 60 + m

    ds = parse_time(day_start)
    de = parse_time(day_end)
    if ds is None or de is None:
        return None

    intervals = []
    for cal in calendars:
        offset, busy = cal
        for iv in busy:
            st, en = iv
            s = parse_time(st)
            e = parse_time(en)
            if s is None or e is None:
                return None
            if e <= s:
                continue
            us = s - offset
            ue = e - offset
            cs = max(us, ds)
            ce = min(ue, de)
            if ce > cs:
                intervals.append((cs, ce))

    if de <= ds:
        return []

    intervals.sort(key=lambda x: (x[0], x[1]))
    merged = []
    for s, e in intervals:
        if merged and s <= merged[-1][1]:
            if e > merged[-1][1]:
                merged[-1] = (merged[-1][0], e)
        else:
            merged.append((s, e))

    def fmt(m):
        if m == 1440:
            return '24:00'
        return '%02d:%02d' % (m // 60, m % 60)

    slots = []
    cursor = ds
    for s, e in merged:
        if s > cursor and s - cursor >= min_len:
            slots.append([fmt(cursor), fmt(s)])
        if e > cursor:
            cursor = e
    if de > cursor and de - cursor >= min_len:
        slots.append([fmt(cursor), fmt(de)])
    return slots

def decode_repeat(text):
    LIMIT = 10000
    n = len(text)
    root = {'parts': [], 'length': 0, 'overflow': False}
    stack = []

    def current():
        return stack[-1] if stack else root

    def add_str(cur, s):
        if cur['overflow']:
            return
        cur['parts'].append(s)
        cur['length'] += len(s)
        if cur['length'] > LIMIT:
            cur['overflow'] = True
            cur['parts'] = None
            cur['length'] = LIMIT + 1

    i = 0
    while i < n:
        c = text[i]
        if c == '\\':
            if i + 1 >= n:
                return None
            add_str(current(), text[i + 1])
            i += 2
            continue
        if '0' <= c <= '9':
            j = i
            while j < n and '0' <= text[j] <= '9':
                j += 1
            if j < n and text[j] == '[':
                count = int(text[i:j])
                stack.append({'count': count, 'parts': [], 'length': 0, 'overflow': False})
                i = j + 1
                continue
            add_str(current(), text[i:j])
            i = j
            continue
        if c == '[':
            return None
        if c == ']':
            if not stack:
                return None
            frame = stack.pop()
            count = frame['count']
            content_length = frame['length']
            if count > 0 and content_length > 0:
                total = count * content_length
                if total <= LIMIT and frame['parts'] is not None:
                    content = ''.join(frame['parts'])
                    parent = current()
                    if not parent['overflow']:
                        new_length = parent['length'] + total
                        if new_length <= LIMIT:
                            parent['parts'].append(content * count)
                            parent['length'] = new_length
                        else:
                            parent['overflow'] = True
                            parent['parts'] = None
                            parent['length'] = LIMIT + 1
                else:
                    parent = current()
                    parent['overflow'] = True
                    parent['parts'] = None
                    parent['length'] = LIMIT + 1
            i += 1
            continue
        add_str(current(), c)
        i += 1

    if stack:
        return None
    if root['overflow'] or root['length'] > LIMIT:
        return None
    return ''.join(root['parts'])

def bool_minterms(expr):
    if not isinstance(expr, str):
        return None

    def tokenize(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c == ' ':
                i += 1
                continue
            if 'a' <= c <= 'z':
                j = i + 1
                while j < n and 'a' <= s[j] <= 'z':
                    j += 1
                tokens.append(('var', s[i:j]))
                i = j
                continue
            if '0' <= c <= '9':
                j = i + 1
                while j < n and '0' <= s[j] <= '9':
                    j += 1
                digits = s[i:j]
                if digits != '0' and digits != '1':
                    return None
                tokens.append(('const', digits))
                i = j
                continue
            if c in '!&^|':
                tokens.append(('op', c))
                i += 1
                continue
            if c == '-':
                if i + 1 < n and s[i + 1] == '>':
                    tokens.append(('op', '->'))
                    i += 2
                    continue
                return None
            if c == '(':
                tokens.append(('lparen', '('))
                i += 1
                continue
            if c == ')':
                tokens.append(('rparen', ')'))
                i += 1
                continue
            return None
        return tokens

    tokens = tokenize(expr)
    if tokens is None:
        return None

    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return None

    def consume():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_implication():
        left = parse_or()
        tok = peek()
        if tok is not None and tok[0] == 'op' and tok[1] == '->':
            consume()
            right = parse_implication()
            return ('->', left, right)
        return left

    def parse_or():
        left = parse_xor()
        while True:
            tok = peek()
            if tok is not None and tok[0] == 'op' and tok[1] == '|':
                consume()
                right = parse_xor()
                left = ('|', left, right)
            else:
                return left

    def parse_xor():
        left = parse_and()
        while True:
            tok = peek()
            if tok is not None and tok[0] == 'op' and tok[1] == '^':
                consume()
                right = parse_and()
                left = ('^', left, right)
            else:
                return left

    def parse_and():
        left = parse_unary()
        while True:
            tok = peek()
            if tok is not None and tok[0] == 'op' and tok[1] == '&':
                consume()
                right = parse_unary()
                left = ('&', left, right)
            else:
                return left

    def parse_unary():
        tok = peek()
        if tok is not None and tok[0] == 'op' and tok[1] == '!':
            consume()
            return ('!', parse_unary())
        return parse_primary()

    def parse_primary():
        tok = peek()
        if tok is None:
            raise ValueError('invalid')
        if tok[0] == 'var':
            consume()
            return ('var', tok[1])
        if tok[0] == 'const':
            consume()
            return ('const', tok[1])
        if tok[0] == 'lparen':
            consume()
            node = parse_implication()
            tok2 = peek()
            if tok2 is None or tok2[0] != 'rparen':
                raise ValueError('invalid')
            consume()
            return node
        raise ValueError('invalid')

    try:
        ast = parse_implication()
        if pos != len(tokens):
            return None
    except ValueError:
        return None

    variable_set = set()

    def collect(node):
        tag = node[0]
        if tag == 'var':
            variable_set.add(node[1])
        elif tag == 'const':
            pass
        elif tag == '!':
            collect(node[1])
        else:
            collect(node[1])
            collect(node[2])

    collect(ast)
    variables = sorted(variable_set)

    def evaluate(node, values):
        tag = node[0]
        if tag == 'var':
            return values[node[1]]
        if tag == 'const':
            return node[1] == '1'
        if tag == '!':
            return not evaluate(node[1], values)
        if tag == '&':
            return evaluate(node[1], values) and evaluate(node[2], values)
        if tag == '^':
            return evaluate(node[1], values) != evaluate(node[2], values)
        if tag == '|':
            return evaluate(node[1], values) or evaluate(node[2], values)
        if tag == '->':
            return (not evaluate(node[1], values)) or evaluate(node[2], values)
        raise ValueError('invalid')

    minterms = []
    n = len(variables)
    for index in range(1 << n):
        values = {}
        for pos0, variable in enumerate(variables):
            values[variable] = ((index >> (n - 1 - pos0)) & 1) != 0
        if evaluate(ast, values):
            minterms.append(index)

    return [variables, minterms]

import sys

def poly_expand(expr):
    if not isinstance(expr, str):
        return None

    old_int_limit = None
    if hasattr(sys, "set_int_max_str_digits"):
        try:
            old_int_limit = sys.get_int_max_str_digits()
            sys.set_int_max_str_digits(0)
        except Exception:
            old_int_limit = None

    old_recursion = None
    try:
        old_recursion = sys.getrecursionlimit()
        sys.setrecursionlimit(10000)
    except Exception:
        old_recursion = None

    try:
        tokens = []
        i = 0
        n = len(expr)
        while i < n:
            ch = expr[i]
            if ch == ' ':
                i += 1
                continue
            if '0' <= ch <= '9':
                j = i
                while j < n and '0' <= expr[j] <= '9':
                    j += 1
                tokens.append(('int', expr[i:j]))
                i = j
                continue
            if ch in 'x+-*^()':
                tokens.append((ch, ch))
                i += 1
                continue
            return None

        pos = 0
        N = len(tokens)

        class Invalid(Exception):
            pass

        def peek():
            if pos < N:
                return tokens[pos]
            return None

        def advance():
            nonlocal pos
            t = tokens[pos]
            pos += 1
            return t

        def add_poly(p, q, sign):
            r = dict(p)
            for k, v in q.items():
                r[k] = r.get(k, 0) + sign * v
            return {k: v for k, v in r.items() if v != 0}

        def mul_poly(p, q):
            r = {}
            for a_deg, a in p.items():
                if a == 0:
                    continue
                for b_deg, b in q.items():
                    if b == 0:
                        continue
                    key = a_deg + b_deg
                    r[key] = r.get(key, 0) + a * b
            return {k: v for k, v in r.items() if v != 0}

        def pow_poly(p, e):
            if e == 0:
                return {0: 1}
            r = {0: 1}
            for _ in range(e):
                r = mul_poly(r, p)
            return r

        def parse_base():
            t = peek()
            if t is None:
                raise Invalid()
            kind = t[0]
            if kind == 'int':
                advance()
                return {0: int(t[1])}
            if kind == 'x':
                advance()
                return {1: 1}
            if kind == '(':
                advance()
                p = parse_expr()
                t2 = peek()
                if t2 is None or t2[0] != ')':
                    raise Invalid()
                advance()
                return p
            raise Invalid()

        def parse_factor():
            t = peek()
            if t is not None and t[0] == '-':
                advance()
                p = parse_factor()
                return {k: -v for k, v in p.items() if v != 0}
            base = parse_base()
            t = peek()
            if t is not None and t[0] == '^':
                advance()
                t = peek()
                if t is None or t[0] != 'int':
                    raise Invalid()
                advance()
                e = int(t[1])
                if e > 20:
                    raise Invalid()
                return pow_poly(base, e)
            return base

        def parse_term():
            p = parse_factor()
            while True:
                t = peek()
                if t is not None and t[0] == '*':
                    advance()
                    q = parse_factor()
                    p = mul_poly(p, q)
                else:
                    return p

        def parse_expr():
            p = parse_term()
            while True:
                t = peek()
                if t is not None and (t[0] == '+' or t[0] == '-'):
                    sign = 1 if t[0] == '+' else -1
                    advance()
                    q = parse_term()
                    p = add_poly(p, q, sign)
                else:
                    return p

        try:
            poly = parse_expr()
            if peek() is not None:
                return None
        except Invalid:
            return None
        except RecursionError:
            return None

        if not poly:
            return '0'

        parts = []
        for idx, d in enumerate(sorted(poly.keys(), reverse=True)):
            c = poly[d]
            mag = abs(c)
            if d == 0:
                s = str(mag)
            else:
                s = ('' if mag == 1 else str(mag)) + 'x'
                if d > 1:
                    s += '^' + str(d)
            if idx == 0:
                parts.append(('-' if c < 0 else '') + s)
            else:
                parts.append(('-' if c < 0 else '+') + s)
        return ''.join(parts)
    finally:
        if old_int_limit is not None:
            try:
                sys.set_int_max_str_digits(old_int_limit)
            except Exception:
                pass
        if old_recursion is not None:
            try:
                sys.setrecursionlimit(old_recursion)
            except Exception:
                pass

import re


def spreadsheet_eval(cells):
    def expand_range(a, b):
        col_a = ord(a[0]) - 65
        row_a = int(a[1:])
        col_b = ord(b[0]) - 65
        row_b = int(b[1:])
        top = min(row_a, row_b)
        bottom = max(row_a, row_b)
        left = min(col_a, col_b)
        right = max(col_a, col_b)
        names = []
        for r in range(top, bottom + 1):
            for c in range(left, right + 1):
                names.append(chr(65 + c) + str(r))
        return names

    def refs_of(node):
        tag = node[0]
        if tag == 'int':
            return []
        if tag == 'ref':
            return [node[1]]
        if tag == 'sum':
            return expand_range(node[1], node[2])
        if tag == 'neg':
            return refs_of(node[1])
        if tag == 'add' or tag == 'sub' or tag == 'mul':
            return refs_of(node[1]) + refs_of(node[2])
        raise AssertionError(tag)

    def tokenize(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c == ' ':
                i += 1
                continue
            if s.startswith('SUM(', i):
                tokens.append(('SUM(', 'SUM('))
                i += 4
                continue
            if '0' <= c <= '9':
                j = i
                while j < n and '0' <= s[j] <= '9':
                    j += 1
                tokens.append(('INT', s[i:j]))
                i = j
                continue
            if 'A' <= c <= 'Z':
                j = i + 1
                while j < n and '0' <= s[j] <= '9':
                    j += 1
                name = s[i:j]
                if j == i + 1 or re.fullmatch(r'[A-Z]([1-9]|[1-9][0-9])', name) is None:
                    raise SyntaxError('invalid reference')
                tokens.append(('REF', name))
                i = j
                continue
            if c in '+-*():':
                tokens.append((c, c))
                i += 1
                continue
            raise SyntaxError('invalid character')
        return tokens

    def parse(tokens):
        pos = 0

        def peek():
            if pos < len(tokens):
                return tokens[pos]
            return None

        def parse_expr():
            nonlocal pos
            node = parse_term()
            while True:
                t = peek()
                if t is not None and t[0] in ('+', '-'):
                    op = t[0]
                    pos += 1
                    rhs = parse_term()
                    node = ('add' if op == '+' else 'sub', node, rhs)
                else:
                    return node

        def parse_term():
            nonlocal pos
            node = parse_unary()
            while True:
                t = peek()
                if t is not None and t[0] == '*':
                    pos += 1
                    rhs = parse_unary()
                    node = ('mul', node, rhs)
                else:
                    return node

        def parse_unary():
            nonlocal pos
            t = peek()
            if t is not None and t[0] == '-':
                pos += 1
                return ('neg', parse_unary())
            return parse_primary()

        def parse_primary():
            nonlocal pos
            t = peek()
            if t is None:
                raise SyntaxError('unexpected end of formula')
            if t[0] == 'INT':
                pos += 1
                return ('int', int(t[1]))
            if t[0] == 'REF':
                pos += 1
                return ('ref', t[1])
            if t[0] == 'SUM(':
                pos += 1
                t2 = peek()
                if t2 is None or t2[0] != 'REF':
                    raise SyntaxError('expected reference')
                a = t2[1]
                pos += 1
                t3 = peek()
                if t3 is None or t3[0] != ':':
                    raise SyntaxError('expected colon')
                pos += 1
                t4 = peek()
                if t4 is None or t4[0] != 'REF':
                    raise SyntaxError('expected reference')
                b = t4[1]
                pos += 1
                t5 = peek()
                if t5 is None or t5[0] != ')':
                    raise SyntaxError('expected closing parenthesis')
                pos += 1
                return ('sum', a, b)
            if t[0] == '(':
                pos += 1
                node = parse_expr()
                t2 = peek()
                if t2 is None or t2[0] != ')':
                    raise SyntaxError('expected closing parenthesis')
                pos += 1
                return node
            raise SyntaxError('unexpected token')

        node = parse_expr()
        if pos != len(tokens):
            raise SyntaxError('trailing tokens')
        return node

    infos = {}
    for name, raw in cells.items():
        if isinstance(raw, str) and raw.startswith('='):
            try:
                ast = parse(tokenize(raw[1:]))
                infos[name] = ('formula', ast, refs_of(ast))
            except Exception:
                infos[name] = ('error', '#SYNTAX', [])
        elif isinstance(raw, str) and re.fullmatch(r'-?[0-9]+', raw):
            infos[name] = ('int', int(raw), [])
        else:
            infos[name] = ('error', '#VALUE', [])

    cyclic = set()

    def reaches_self(start):
        stack = list(infos[start][2])
        seen = set()
        while stack:
            cur = stack.pop()
            if cur == start:
                return True
            if cur in seen:
                continue
            seen.add(cur)
            info2 = infos.get(cur)
            if info2 is not None and info2[0] == 'formula':
                stack.extend(info2[2])
        return False

    for name, info in infos.items():
        if info[0] == 'formula' and reaches_self(name):
            cyclic.add(name)

    values = {}

    def value(name):
        if name not in infos:
            return 0
        cached = values.get(name)
        if cached is not None:
            return cached
        info = infos[name]
        if info[0] == 'int':
            values[name] = info[1]
            return info[1]
        if info[0] == 'error':
            values[name] = info[1]
            return info[1]
        if name in cyclic:
            values[name] = '#CYCLE'
            return '#CYCLE'
        for r in info[2]:
            rv = value(r)
            if isinstance(rv, str):
                values[name] = rv
                return rv
        v = eval_ast(info[1])
        values[name] = v
        return v

    def eval_ast(node):
        tag = node[0]
        if tag == 'int':
            return node[1]
        if tag == 'ref':
            return value(node[1])
        if tag == 'sum':
            total = 0
            for nm in expand_range(node[1], node[2]):
                total += value(nm)
            return total
        if tag == 'neg':
            return -eval_ast(node[1])
        if tag == 'add':
            return eval_ast(node[1]) + eval_ast(node[2])
        if tag == 'sub':
            return eval_ast(node[1]) - eval_ast(node[2])
        if tag == 'mul':
            return eval_ast(node[1]) * eval_ast(node[2])
        raise AssertionError(tag)

    result = {}
    for name in cells:
        result[name] = value(name)
    return result

def common_free_slots(calendars, day_start, day_end, min_len):
    if min_len < 1:
        return None

    def parse_time(s):
        if not isinstance(s, str) or len(s) != 5 or s[2] != ':':
            return None
        hh, mm = s[:2], s[3:]
        if not (all('0' <= c <= '9' for c in hh) and all('0' <= c <= '9' for c in mm)):
            return None
        h = int(hh)
        m = int(mm)
        if h == 24:
            return 1440 if m == 0 else None
        if h > 23 or m > 59:
            return None
        return h * 60 + m

    def fmt(m):
        if m == 1440:
            return '24:00'
        return f'{m // 60:02d}:{m % 60:02d}'

    ds = parse_time(day_start)
    de = parse_time(day_end)
    if ds is None or de is None:
        return None

    intervals = []
    for item in calendars:
        offset = item[0]
        busy = item[1]
        for iv in busy:
            s = parse_time(iv[0])
            e = parse_time(iv[1])
            if s is None or e is None:
                return None
            if e <= s:
                continue
            intervals.append((s - offset, e - offset))

    if de <= ds:
        return []

    clipped = []
    for a, b in intervals:
        a = max(a, ds)
        b = min(b, de)
        if b > a:
            clipped.append((a, b))
    clipped.sort(key=lambda p: p[0])

    merged = []
    for a, b in clipped:
        if merged and a <= merged[-1][1]:
            if b > merged[-1][1]:
                merged[-1] = (merged[-1][0], b)
        else:
            merged.append((a, b))

    free = []
    cur = ds
    for a, b in merged:
        if a > cur and a - cur >= min_len:
            free.append((cur, a))
        if b > cur:
            cur = b
    if de > cur and de - cur >= min_len:
        free.append((cur, de))

    return [[fmt(a), fmt(b)] for a, b in free]

def lex_shortest_path(edges, src, dst):
    from heapq import heappush, heappop

    for u, v, w in edges:
        if w < 1:
            return None

    adj = {}
    rev = {}
    for u, v, w in edges:
        adj.setdefault(u, []).append((v, w))
        rev.setdefault(v, []).append((u, w))

    if src == dst:
        return [0, [src]]

    INF = float('inf')

    dist = {src: 0}
    pq = [(0, src)]
    while pq:
        d, u = heappop(pq)
        if d != dist.get(u):
            continue
        for v, w in adj.get(u, ()):
            nd = d + w
            if nd < dist.get(v, INF):
                dist[v] = nd
                heappush(pq, (nd, v))

    if dst not in dist:
        return None

    d2 = {dst: 0}
    pq = [(0, dst)]
    while pq:
        d, u = heappop(pq)
        if d != d2.get(u):
            continue
        for v, w in rev.get(u, ()):
            nd = d + w
            if nd < d2.get(v, INF):
                d2[v] = nd
                heappush(pq, (nd, v))

    total = dist[dst]
    path = [src]
    cur = src
    while cur != dst:
        best_v = None
        dcur = dist[cur]
        for v, w in adj.get(cur, ()):
            if dcur + w + d2.get(v, INF) == total:
                if best_v is None or v < best_v:
                    best_v = v
        path.append(best_v)
        cur = best_v

    return [total, path]

def shell_words(line, env):
    def is_name_start(c):
        return ('A' <= c <= 'Z') or ('a' <= c <= 'z') or c == '_'

    def is_name_char(c):
        return is_name_start(c) or ('0' <= c <= '9')

    words = []
    cur = []
    has_quoted = False
    i = 0
    n = len(line)

    def flush():
        nonlocal cur, has_quoted
        if cur or has_quoted:
            words.append(''.join(cur))
        cur = []
        has_quoted = False

    def expand(i):
        nonlocal cur
        if i + 1 >= n:
            cur.append('$')
            return i + 1
        nxt = line[i + 1]
        if nxt == '{':
            j = line.find('}', i + 2)
            if j == -1:
                return None
            name = line[i + 2:j]
            if not name or not is_name_start(name[0]) or not all(is_name_char(c) for c in name[1:]):
                return None
            value = env.get(name, '')
            if value:
                cur.append(value)
            return j + 1
        if is_name_start(nxt):
            j = i + 1
            while j < n and is_name_char(line[j]):
                j += 1
            name = line[i + 1:j]
            value = env.get(name, '')
            if value:
                cur.append(value)
            return j
        cur.append('$')
        return i + 1

    while i < n:
        c = line[i]
        if c == ' ' or c == '\t':
            flush()
            i += 1
            continue
        if c == '\\':
            if i + 1 >= n:
                return None
            cur.append(line[i + 1])
            i += 2
            continue
        if c == "'":
            j = line.find("'", i + 1)
            if j == -1:
                return None
            text = line[i + 1:j]
            if text:
                cur.append(text)
            has_quoted = True
            i = j + 1
            continue
        if c == '"':
            has_quoted = True
            i += 1
            while True:
                if i >= n:
                    return None
                ch = line[i]
                if ch == '"':
                    i += 1
                    break
                if ch == '\\':
                    if i + 1 < n and line[i + 1] in ('"', '\\', '$'):
                        cur.append(line[i + 1])
                        i += 2
                        continue
                    cur.append('\\')
                    i += 1
                    continue
                if ch == '$':
                    new_i = expand(i)
                    if new_i is None:
                        return None
                    i = new_i
                    continue
                cur.append(ch)
                i += 1
            continue
        if c == '$':
            new_i = expand(i)
            if new_i is None:
                return None
            i = new_i
            continue
        cur.append(c)
        i += 1

    flush()
    return words

import heapq

def lex_shortest_path(edges, src, dst):
    for u, v, w in edges:
        if w < 1:
            return None
    if src == dst:
        return [0, [src]]

    adj = {}
    rev = {}
    for u, v, w in edges:
        adj.setdefault(u, []).append((v, w))
        rev.setdefault(v, []).append((u, w))

    INF = float('inf')
    fwd = {src: 0}
    heap = [(0, src)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != fwd.get(u):
            continue
        for v, w in adj.get(u, ()):
            nd = d + w
            if nd < fwd.get(v, INF):
                fwd[v] = nd
                heapq.heappush(heap, (nd, v))

    if dst not in fwd:
        return None
    total = fwd[dst]

    bwd = {dst: 0}
    heap = [(0, dst)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != bwd.get(u):
            continue
        for v, w in rev.get(u, ()):
            nd = d + w
            if nd < bwd.get(v, INF):
                bwd[v] = nd
                heapq.heappush(heap, (nd, v))

    path = [src]
    cur = src
    while cur != dst:
        du = fwd[cur]
        best = None
        for v, w in adj.get(cur, ()):
            nd = du + w
            if fwd.get(v) == nd and fwd[v] + bwd.get(v, INF) == total:
                if best is None or v < best:
                    best = v
        if best is None:
            return None
        path.append(best)
        cur = best
    return [total, path]

def lru_ttl(capacity, ops):
    cache = {}
    results = []
    for op in ops:
        if op[0] == 'set':
            t = op[1]
            key = op[2]
            value = op[3]
            ttl = op[4]
            if ttl <= 0:
                cache.pop(key, None)
                continue
            exp = t + ttl
            for k in [k for k, entry in cache.items() if t >= entry[1]]:
                del cache[k]
            if key in cache:
                cache.pop(key)
                cache[key] = (value, exp)
            else:
                if capacity == 0:
                    continue
                if len(cache) >= capacity:
                    cache.pop(next(iter(cache)))
                cache[key] = (value, exp)
        else:
            t = op[1]
            key = op[2]
            entry = cache.get(key)
            if entry is not None and t < entry[1]:
                results.append(entry[0])
                cache.pop(key)
                cache[key] = entry
            else:
                results.append(None)
    return results

from collections import OrderedDict

def lru_ttl(capacity, ops):
    cache = OrderedDict()
    results = []
    for op in ops:
        if op[0] == 'set':
            t, key, value, ttl = op[1], op[2], op[3], op[4]
            if ttl <= 0:
                cache.pop(key, None)
                continue
            for k in list(cache.keys()):
                if t >= cache[k][1]:
                    del cache[k]
            if key in cache:
                cache[key] = (value, t + ttl)
                cache.move_to_end(key)
            else:
                if capacity == 0:
                    continue
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = (value, t + ttl)
        else:
            t, key = op[1], op[2]
            entry = cache.get(key)
            if entry is not None and t < entry[1]:
                results.append(entry[0])
                cache.move_to_end(key)
            else:
                results.append(None)
    return results

def league_table(matches):
    valid_matches = []
    stats = {}

    for home, away, home_goals, away_goals in matches:
        if home == away:
            continue
        if home_goals < 0 or away_goals < 0:
            continue

        valid_matches.append((home, away, home_goals, away_goals))

        for team in (home, away):
            if team not in stats:
                stats[team] = {
                    "played": 0,
                    "won": 0,
                    "drawn": 0,
                    "lost": 0,
                    "goals_for": 0,
                    "goals_against": 0,
                    "points": 0,
                }

        h = stats[home]
        a = stats[away]
        h["played"] += 1
        a["played"] += 1
        h["goals_for"] += home_goals
        h["goals_against"] += away_goals
        a["goals_for"] += away_goals
        a["goals_against"] += home_goals

        if home_goals > away_goals:
            h["won"] += 1
            h["points"] += 3
            a["lost"] += 1
        elif home_goals < away_goals:
            a["won"] += 1
            a["points"] += 3
            h["lost"] += 1
        else:
            h["drawn"] += 1
            a["drawn"] += 1
            h["points"] += 1
            a["points"] += 1

    by_points = {}
    for name, s in stats.items():
        by_points.setdefault(s["points"], []).append(name)

    rows = []
    for name, s in stats.items():
        group = set(by_points[s["points"]])
        h2h_points = 0
        h2h_gd = 0

        for home, away, home_goals, away_goals in valid_matches:
            if home in group and away in group:
                if home == name:
                    h2h_gd += home_goals - away_goals
                    if home_goals > away_goals:
                        h2h_points += 3
                    elif home_goals == away_goals:
                        h2h_points += 1
                elif away == name:
                    h2h_gd += away_goals - home_goals
                    if away_goals > home_goals:
                        h2h_points += 3
                    elif away_goals == home_goals:
                        h2h_points += 1

        overall_gd = s["goals_for"] - s["goals_against"]
        rows.append({
            "name": name,
            "played": s["played"],
            "won": s["won"],
            "drawn": s["drawn"],
            "lost": s["lost"],
            "goals_for": s["goals_for"],
            "goals_against": s["goals_against"],
            "points": s["points"],
            "h2h_points": h2h_points,
            "h2h_gd": h2h_gd,
            "overall_gd": overall_gd,
        })

    rows.sort(key=lambda r: (
        -r["points"],
        -r["h2h_points"],
        -r["h2h_gd"],
        -r["overall_gd"],
        -r["goals_for"],
        r["name"],
    ))

    return [
        [r["name"], r["played"], r["won"], r["drawn"], r["lost"], r["goals_for"], r["goals_against"], r["points"]]
        for r in rows
    ]

def canonical_huffman(freqs):
    agg = {}
    for entry in freqs:
        symbol, weight = entry[0], entry[1]
        if weight <= 0:
            continue
        agg[symbol] = agg.get(symbol, 0) + weight
    if not agg:
        return []
    if len(agg) == 1:
        sym = next(iter(agg))
        return [[sym, "0"]]

    nodes = [[w, sym, {sym: 0}] for sym, w in agg.items()]
    while len(nodes) > 1:
        nodes.sort(key=lambda n: (n[0], n[1]))
        n1 = nodes.pop(0)
        n2 = nodes.pop(0)
        leaves = {}
        for sym, d in n1[2].items():
            leaves[sym] = d + 1
        for sym, d in n2[2].items():
            leaves[sym] = d + 1
        key = n1[1] if n1[1] < n2[1] else n2[1]
        nodes.append([n1[0] + n2[0], key, leaves])

    depths = nodes[0][2]
    symbols = sorted(depths, key=lambda s: (depths[s], s))

    out = []
    prev_code = None
    prev_len = None
    for i, sym in enumerate(symbols):
        length = depths[sym]
        if i == 0:
            code = 0
        else:
            code = (prev_code + 1) << (length - prev_len)
        bits = format(code, "0{}b".format(length))
        out.append([sym, bits])
        prev_code = code
        prev_len = length
    return out

def rational_eval(expr):
    from fractions import Fraction

    if not isinstance(expr, str):
        return 'error'

    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c == ' ' or c == '\t':
            i += 1
            continue
        if '0' <= c <= '9':
            value = 0
            j = i
            while j < n and '0' <= expr[j] <= '9':
                value = value * 10 + (ord(expr[j]) - 48)
                j += 1
            tokens.append(('int', value))
            i = j
            continue
        if c in '+-*/^()':
            tokens.append((c, None))
            i += 1
            continue
        return 'error'

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError('unexpected end of input')
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        v = parse_term()
        while True:
            tok = peek()
            if tok is None or tok[0] not in ('+', '-'):
                return v
            advance()
            rhs = parse_term()
            if tok[0] == '+':
                v = v + rhs
            else:
                v = v - rhs

    def parse_term():
        v = parse_unary()
        while True:
            tok = peek()
            if tok is None:
                return v
            if tok[0] == '*':
                advance()
                rhs = parse_unary()
                v = v * rhs
            elif tok[0] == '/':
                advance()
                rhs = parse_unary()
                if rhs == 0:
                    raise ValueError('division by zero')
                v = v / rhs
            else:
                return v

    def parse_unary():
        tok = peek()
        if tok is not None and tok[0] == '-':
            advance()
            return -parse_unary()
        return parse_power()

    def parse_power():
        base = parse_atom()
        tok = peek()
        if tok is not None and tok[0] == '^':
            advance()
            exp = parse_unary()
            return _power(base, exp)
        return base

    def parse_atom():
        tok = peek()
        if tok is None:
            raise ValueError('unexpected end of input')
        if tok[0] == 'int':
            advance()
            return Fraction(tok[1], 1)
        if tok[0] == '(':
            advance()
            v = parse_expr()
            tok2 = peek()
            if tok2 is None or tok2[0] != ')':
                raise ValueError('expected closing parenthesis')
            advance()
            return v
        raise ValueError('unexpected token')

    def _power(base, exp):
        if exp.denominator != 1:
            raise ValueError('exponent must be an integer')
        e = exp.numerator
        if e > 64 or e < -64:
            raise ValueError('exponent out of range')
        if base == 0 and e < 0:
            raise ValueError('zero raised to a negative power')
        if e == 0:
            return Fraction(1, 1)
        return base ** e

    def _int_str(x):
        if x == 0:
            return '0'
        sign = ''
        if x < 0:
            sign = '-'
            x = -x
        digits = []
        while x:
            digits.append(chr(48 + x % 10))
            x //= 10
        return sign + ''.join(reversed(digits))

    try:
        result = parse_expr()
        if pos != len(tokens):
            return 'error'
        if result.denominator == 1:
            return _int_str(result.numerator)
        return _int_str(result.numerator) + '/' + _int_str(result.denominator)
    except Exception:
        return 'error'

def min_coins_lex(coins, amount):
    if amount < 0:
        return None
    if amount == 0:
        return []
    denoms = sorted({c for c in coins if c > 0}, reverse=True)
    if not denoms:
        return None
    dp_count = [None] * (amount + 1)
    dp_list = [None] * (amount + 1)
    dp_count[0] = 0
    dp_list[0] = []
    for a in range(1, amount + 1):
        best_count = None
        best_list = None
        for c in denoms:
            if c > a:
                continue
            pc = dp_count[a - c]
            if pc is None:
                continue
            cnt = pc + 1
            cand = sorted(dp_list[a - c] + [c], reverse=True)
            if best_count is None or cnt < best_count or (cnt == best_count and cand > best_list):
                best_count = cnt
                best_list = cand
        dp_count[a] = best_count
        dp_list[a] = best_list
    return dp_list[amount]

def min_coins_lex(coins, amount):
    if amount < 0:
        return None
    if amount == 0:
        return []
    uniq = sorted({c for c in coins if c > 0}, reverse=True)
    if not uniq:
        return None

    def insert_desc(t, c):
        i = 0
        n = len(t)
        while i < n and t[i] > c:
            i += 1
        return t[:i] + (c,) + t[i:]

    best = [None] * (amount + 1)
    best[0] = (0, ())
    for a in range(1, amount + 1):
        cur = None
        for c in uniq:
            if c > a:
                continue
            prev = best[a - c]
            if prev is None:
                continue
            cnt = prev[0] + 1
            cand = insert_desc(prev[1], c)
            if cur is None:
                cur = (cnt, cand)
            elif cnt < cur[0] or (cnt == cur[0] and cand > cur[1]):
                cur = (cnt, cand)
        best[a] = cur
    res = best[amount]
    if res is None:
        return None
    return list(res[1])

import re
import calendar
from datetime import date

def monthly_occurrences(start, rule, count):
    if not isinstance(start, str) or not isinstance(rule, str):
        return None
    m = re.fullmatch(r'([0-9]{4})-([0-9]{2})-([0-9]{2})', start)
    if not m:
        return None
    try:
        start_date = date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        return None

    day_m = re.fullmatch(r'day:(-?)([1-9]|[12][0-9]|3[01])', rule)
    nth_m = re.fullmatch(r'nth:(-?)([1-5]):(mon|tue|wed|thu|fri|sat|sun)', rule)
    if day_m:
        kind = 'day'
        negative = day_m.group(1) == '-'
        n = int(day_m.group(2))
    elif nth_m:
        kind = 'nth'
        negative = nth_m.group(1) == '-'
        n = int(nth_m.group(2))
        wd = nth_m.group(3)
    else:
        return None

    if count <= 0:
        return []

    weekdays = ('mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun')
    results = []
    year = start_date.year
    month = start_date.month

    while (year, month) <= (9999, 12) and len(results) < count:
        last_day = calendar.monthrange(year, month)[1]
        candidate = None
        if kind == 'day':
            if negative:
                day = last_day - n + 1
                if day >= 1:
                    candidate = date(year, month, day)
            else:
                if n <= last_day:
                    candidate = date(year, month, n)
        else:
            days = [day for day in range(1, last_day + 1)
                    if weekdays[date(year, month, day).weekday()] == wd]
            if negative:
                if len(days) >= n:
                    candidate = date(year, month, days[-n])
            else:
                if len(days) >= n:
                    candidate = date(year, month, days[n - 1])

        if candidate is not None and candidate >= start_date:
            results.append(candidate.isoformat())

        if month == 12:
            month = 1
            year += 1
        else:
            month += 1

    return results

def json_select(doc, path):
    if not isinstance(path, str):
        return None
    if not path.startswith('$'):
        return None
    steps = []
    i = 1
    length = len(path)

    def match_name(pos):
        if pos >= length:
            return None
        c = path[pos]
        if not (('A' <= c <= 'Z') or ('a' <= c <= 'z') or c == '_'):
            return None
        j = pos + 1
        while j < length:
            c = path[j]
            if ('A' <= c <= 'Z') or ('a' <= c <= 'z') or ('0' <= c <= '9') or c == '_':
                j += 1
            else:
                break
        return path[pos:j], j

    while i < length:
        c = path[i]
        if c == '.':
            if path.startswith('..', i):
                m = match_name(i + 2)
                if m is None:
                    return None
                name, j = m
                steps.append(('recurse', name))
                i = j
                continue
            m = match_name(i + 1)
            if m is None:
                return None
            name, j = m
            steps.append(('key', name))
            i = j
            continue
        if c == '[':
            if path.startswith('[*]', i):
                steps.append(('star',))
                i += 3
                continue
            j = i + 1
            if j < length and path[j] == "'":
                j += 1
                chars = []
                while True:
                    if j >= length:
                        return None
                    ch = path[j]
                    if ch == '\\':
                        if j + 1 >= length:
                            return None
                        esc = path[j + 1]
                        if esc == "'":
                            chars.append("'")
                            j += 2
                            continue
                        if esc == '\\':
                            chars.append('\\')
                            j += 2
                            continue
                        return None
                    if ch == "'":
                        if j + 1 >= length or path[j + 1] != ']':
                            return None
                        j += 2
                        steps.append(('key', ''.join(chars)))
                        break
                    chars.append(ch)
                    j += 1
                i = j
                continue
            sign = ''
            if j < length and path[j] == '-':
                sign = '-'
                j += 1
            start = j
            while j < length:
                ch = path[j]
                if '0' <= ch <= '9':
                    j += 1
                else:
                    break
            if j == start:
                return None
            digits = path[start:j]
            if len(digits) > 1 and digits[0] == '0':
                return None
            if j >= length or path[j] != ']':
                return None
            steps.append(('index', int(sign + digits)))
            i = j + 1
            continue
        return None

    current = [doc]
    for step in steps:
        kind = step[0]
        new = []
        if kind == 'key':
            name = step[1]
            for v in current:
                if isinstance(v, dict) and name in v:
                    new.append(v[name])
        elif kind == 'index':
            num = step[1]
            for v in current:
                if isinstance(v, list):
                    L = len(v)
                    if num >= 0:
                        if num < L:
                            new.append(v[num])
                    else:
                        idx = L + num
                        if 0 <= idx < L:
                            new.append(v[idx])
        elif kind == 'star':
            for v in current:
                if isinstance(v, list):
                    new.extend(v)
                elif isinstance(v, dict):
                    new.extend(v.values())
        else:
            name = step[1]
            for v in current:
                stack = [v]
                while stack:
                    node = stack.pop()
                    if isinstance(node, dict):
                        if name in node:
                            new.append(node[name])
                        for value in reversed(list(node.values())):
                            stack.append(value)
                    elif isinstance(node, list):
                        for item in reversed(node):
                            stack.append(item)
        current = new
    return current

def bool_minterms(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c == ' ':
            i += 1
            continue
        if c == '(':
            tokens.append(('(',))
            i += 1
            continue
        if c == ')':
            tokens.append((')',))
            i += 1
            continue
        if c == '!':
            tokens.append(('!',))
            i += 1
            continue
        if c == '&':
            tokens.append(('&',))
            i += 1
            continue
        if c == '^':
            tokens.append(('^',))
            i += 1
            continue
        if c == '|':
            tokens.append(('|',))
            i += 1
            continue
        if c == '-':
            if i + 1 < n and expr[i + 1] == '>':
                tokens.append(('->',))
                i += 2
                continue
            return None
        if '0' <= c <= '9':
            j = i
            while j < n and '0' <= expr[j] <= '9':
                j += 1
            run = expr[i:j]
            if run == '0':
                tokens.append(('const', False))
            elif run == '1':
                tokens.append(('const', True))
            else:
                return None
            i = j
            continue
        if 'a' <= c <= 'z':
            j = i
            while j < n and 'a' <= expr[j] <= 'z':
                j += 1
            tokens.append(('var', expr[i:j]))
            i = j
            continue
        return None

    toks = tokens
    pos = 0

    def peek():
        if pos < len(toks):
            return toks[pos]
        return None

    def advance():
        nonlocal pos
        tok = toks[pos]
        pos += 1
        return tok

    def parse_expr():
        return parse_implication()

    def parse_implication():
        node = parse_or()
        if peek() == ('->',):
            advance()
            node = ('->', node, parse_implication())
        return node

    def parse_or():
        node = parse_xor()
        while peek() == ('|',):
            advance()
            node = ('|', node, parse_xor())
        return node

    def parse_xor():
        node = parse_and()
        while peek() == ('^',):
            advance()
            node = ('^', node, parse_and())
        return node

    def parse_and():
        node = parse_unary()
        while peek() == ('&',):
            advance()
            node = ('&', node, parse_unary())
        return node

    def parse_unary():
        if peek() == ('!',):
            advance()
            return ('!', parse_unary())
        return parse_primary()

    def parse_primary():
        tok = peek()
        if tok is None:
            raise ValueError('unexpected end of input')
        if tok[0] == 'var':
            advance()
            return ('var', tok[1])
        if tok[0] == 'const':
            advance()
            return ('const', tok[1])
        if tok == ('(',):
            advance()
            node = parse_expr()
            if peek() != (')',):
                raise ValueError('expected )')
            advance()
            return node
        raise ValueError('unexpected token')

    try:
        tree = parse_expr()
        if pos != len(toks):
            return None
    except ValueError:
        return None

    varset = set()

    def collect(node):
        t = node[0]
        if t == 'var':
            varset.add(node[1])
        elif t == '!':
            collect(node[1])
        elif t == 'const':
            pass
        else:
            collect(node[1])
            collect(node[2])

    collect(tree)
    variables = sorted(varset)

    def evaluate(node, values):
        t = node[0]
        if t == 'const':
            return node[1]
        if t == 'var':
            return values[node[1]]
        if t == '!':
            return not evaluate(node[1], values)
        if t == '&':
            return evaluate(node[1], values) and evaluate(node[2], values)
        if t == '^':
            return evaluate(node[1], values) != evaluate(node[2], values)
        if t == '|':
            return evaluate(node[1], values) or evaluate(node[2], values)
        if t == '->':
            return (not evaluate(node[1], values)) or evaluate(node[2], values)
        raise ValueError('bad node')

    minterms = []
    m = len(variables)
    for idx in range(1 << m):
        values = {}
        for k, name in enumerate(variables):
            values[name] = bool((idx >> (m - 1 - k)) & 1)
        if evaluate(tree, values):
            minterms.append(idx)
    return [variables, minterms]
